// 由 tools/build-desc.js 產生，不要手改。[標題西, 標題英, 標題英(簡), 說明繁, 說明簡, 說明西, 說明英]
window.GDESC=Object.assign(window.GDESC||{},{"3-1-0":["Si…: …的話","…的話 if, supposing","…的话 if, supposing","A 的話，B：如果 A 發生，就 B。口語常和「如果」「要是」一起用。","A 的话，B：如果 A 发生，就 B。口语常和「如果」「要是」一起用。","A 的話，B = si A, entonces B (condicional coloquial). Se combina con 如果 / 要是.","A 的話，B = if A, then B (colloquial conditional). Often used with 如果 or 要是."],"3-1-1":["Menos de: 不到","不到 less than","","不到＋數量：比那個數量還少。","不到＋数量：比那个数量还少。","不到 + cantidad = menos de.","不到 + quantity = less than that amount."],"3-1-2":["Por poco: 差一點","差一點（就）… almost","差一点（就）… almost","差一點(就)＋動詞：幾乎發生，但最後沒發生。","差一点(就)＋动词：几乎发生，但最后没发生。","差一點(就) + verbo = por poco ocurre (pero no ocurrió).","差一點(就) + verb = almost happened, but in the end did not."],"3-1-3":["Me temo que: 恐怕","恐怕… probably","","恐怕：擔心或推測不太好的事情可能會發生，意思是「我怕…」。","恐怕：担心或推测不太好的事情可能会发生，意思是「我怕…」。","恐怕 = me temo que, probablemente (sobre algo desfavorable).","恐怕 = I'm afraid that…, probably (about something undesirable)."],"3-1-4":["Por fin: 好不容易","好不容易 finally managed to","","好不容易（才）：經過很多困難，終於做到。","好不容易（才）：经过很多困难，终于做到。","好不容易 = con mucha dificultad, por fin logró.","好不容易(才) = after great difficulty, finally managed to."],"3-1-5":["Decir y hacer: 說…就…","Instantly without Prior Warning with 說…就…","Instantly without Prior Warning with 说…就…","說 A 就 A：一說就馬上做，沒有任何預告。","说 A 就 A：一说就马上做，没有任何预告。","說 A 就 A = hacer algo en cuanto se dice, sin previo aviso.","說 A 就 A = does it right away as soon as it's said, with no warning."],"3-1-6":["No importa: 不管…都","不管…都 … regardless of whether or not","","不管＋疑問或選項，都＋結果：不論情況怎麼樣，結果都一樣。","不管＋疑问或选项，都＋结果：不论情况怎么样，结果都一样。","不管 + pregunta u opciones，都… = no importa…, siempre…","不管 + question or alternatives, 都 + result = no matter what, the result is the same."],"3-2-0":["En general: 一般來說","一般來說 generally speaking","一般来说 generally speaking","一般來說：通常的情況是…，不一定每次都這樣。","一般来说：通常的情况是…，不一定每次都这样。","一般來說 = en general, por lo común.","一般來說 = generally, usually (not necessarily every time)."],"3-2-1":["Verbo comodín: 弄","General Verb 弄","","「弄」是萬用動詞，意思會跟著後面的補語變，例如弄壞、弄髒、弄好。","「弄」是万用动词，意思会跟着后面的补语变，例如弄坏、弄脏、弄好。","弄 es un verbo comodín: «hacer, arreglar, estropear» según el complemento: 弄壞, 弄髒, 弄好.","弄 is an all-purpose verb; its meaning depends on the complement: 弄壞 (break), 弄髒 (dirty), 弄好 (fix)."],"3-2-2":["Además: 再說","再說 besides, moreover","再说 besides, moreover","再說：再補充一個理由，意思是「而且」「何況」。","再说：再补充一个理由，意思是「而且」「何况」。","再說 = además, y por si fuera poco (añade otra razón).","再說 = besides, what's more (adds another reason)."],"3-2-3":["Convertir en: V成","V+成 to become, to turn into","","動詞＋成：表示變成、轉換成另一種東西，例如變成、寫成、翻成。","动词＋成：表示变成、转换成另一种东西，例如变成、写成、翻成。","V + 成 = convertir, resultar en: 變成, 寫成, 翻成.","Verb + 成 = turn into, convert to: 變成, 寫成, 翻成."],"3-2-4":["En realidad no: 並","Contrary to Expectation with 並","Contrary to Expectation with 并","並＋不／沒：加強否定，表示事實跟想像或預期不一樣。","并＋不／没：加强否定，表示事实跟想像或预期不一样。","並 + 不 / 沒 = en realidad no. Refuerza una negación contraria a lo que se esperaba.","並 + 不/沒 = actually not; strengthens a negation that goes against expectations."],"3-2-5":["Sobre todo: 尤其是","尤其是 especially","","尤其是：在一群裡特別強調其中一個。","尤其是：在一群里特别强调其中一个。","尤其是 = especialmente. Destaca un caso dentro de un grupo.","尤其是 = especially; singles out one case within a group."],"3-2-6":["No hay remedio: 只好","Concession with 只好 could only, have no choice but to","","只好＋動詞：沒有別的辦法，只能這樣做。","只好＋动词：没有别的办法，只能这样做。","只好 + verbo = no queda más remedio que…","只好 + verb = have no choice but to."],"3-3-0":["Influido por: 受到…影響","受到…的影響 to be influenced by, affected by","受到…的影响 to be influenced by, affected by","受到＋人事物＋的影響：被某人或某事影響。","受到＋人事物＋的影响：被某人或某事影响。","受到 + X + 的影響 = ser influenciado por X.","受到 + X + 的影響 = to be influenced by X."],"3-3-1":["Menos mal: 幸虧","幸虧… fortunately…","幸亏… fortunately…","幸虧 A，B：因為有 A 這個好運，才沒有發生不好的事。","幸亏 A，B：因为有 A 这个好运，才没有发生不好的事。","幸虧 A，B = por suerte A, (de lo contrario habría pasado algo malo).","幸虧 A, B = fortunately A (otherwise something bad would have happened)."],"3-3-2":["Se puede considerar: 算是","算是… can be considered…","","算是：雖然不是百分之百，但可以這樣看。","算是：虽然不是百分之百，但可以这样看。","算是 = se puede considerar (aunque no del todo).","算是 = can be considered (though not entirely)."],"3-3-3":["Sí que: 是…","是… It is indeed true that…","","「是」放在形容詞或動詞前面，要重讀，表示確認、承認「的確如此」。","「是」放在形容词或动词前面，要重读，表示确认、承认「的确如此」。","是 acentuado antes de un adjetivo o verbo confirma algo: «sí que», «en efecto».","A stressed 是 before an adjective or verb confirms something: 'indeed', 'it's true that'."],"3-3-4":["Con razón: 難怪","難怪 no wonder","难怪 no wonder","難怪：知道原因後，覺得結果不奇怪了。","难怪：知道原因后，觉得结果不奇怪了。","難怪 = con razón, no es de extrañar (ahora se entiende la causa).","難怪 = no wonder; now the cause is understood, the result makes sense."],"3-3-5":["Muchísimo: …死了","A Post-verbal Intensifier 死了 terribly","","形容詞或動詞＋死了：非常、極了，口語，多用在強烈的感覺。","形容词或动词＋死了：非常、极了，口语，多用在强烈的感觉。","Adjetivo / verbo + 死了 = muchísimo (coloquial, para sensaciones intensas).","Adj/verb + 死了 = extremely (colloquial, for strong feelings)."],"3-3-6":["Casi: 幾乎","幾乎 almost","几乎 almost","幾乎：差不多、將近，例如幾乎全部、幾乎每天。","几乎：差不多、将近，例如几乎全部、几乎每天。","幾乎 = casi (casi todo, casi siempre, casi ocurre).","幾乎 = almost (almost all, almost every day)."],"3-3-7":["Algo, un poco: 多少","多少 somewhat","","多少＋動詞或形容詞：多多少少、至少有一點。","多少＋动词或形容词：多多少少、至少有一点。","多少 + verbo / adjetivo = en alguna medida, algo, aunque sea un poco.","多少 + verb/adjective = to some extent, at least a little."],"3-3-8":["Por más que: 再…也","再…也… no matter how…, still…","","再＋形容詞或動詞＋也：就算程度很高，結果還是一樣。","再＋形容词或动词＋也：就算程度很高，结果还是一样。","再 + adjetivo / verbo + 也 = por más… que sea, aun así…","再 + adjective/verb + 也 = no matter how…, still…"],"3-4-0":["No solo…también: 不但…還","不但…，還… not only…, but also","不但…，还… not only…, but also","不但 A，還 B：除了 A 以外，還有 B。","不但 A，还 B：除了 A 以外，还有 B。","不但 A，還 B = no solo A, también B.","不但 A，還 B = not only A, but also B."],"3-4-1":["Hablar: 說 vs 談","Speak 說 vs Talk 談","Speak 说 vs Talk 谈","「說」是把話說出口；「談」是就某個主題互相交談、討論。","「说」是把话说出口；「谈」是就某个主题互相交谈、讨论。","說 = decir o hablar (producir palabras). 談 = conversar o discutir un tema con intercambio.","說 = to say or speak (produce words); 談 = to talk over or discuss a topic back and forth."],"3-4-2":["No es…sino: 不是…而是","…不是…，而是… not…; rather…","","不是 A，而是 B：不是 A，真正的是 B。","不是 A，而是 B：不是 A，真正的是 B。","不是 A，而是 B = no es A, sino B.","不是 A，而是 B = it's not A, but B."],"3-4-3":["Nunca: 從來","從來+Negation never","从来+Negation never","從來＋不／沒：到現在都沒有過。","从来＋不／没：到现在都没有过。","從來 + 不 / 沒 (有) = nunca, jamás (hasta ahora).","從來 + 不/沒 = never, not once up to now."],"3-4-4":["Verbo 上: 上課, 上班","Various Meanings of the Verb 上","","「上」有很多用法，像上課、上班、上網、上車，常表示開始或進入某個活動，或是搭上交通工具。","「上」有很多用法，像上课、上班、上网、上车，常表示开始或进入某个活动，或是搭上交通工具。","上 tiene varios sentidos como verbo: 上課, 上班, 上網, 上車 (empezar o ir a una actividad, subir).","上 has several senses as a verb: 上課, 上班, 上網, 上車 (start or go to an activity, get on a vehicle)."],"3-4-5":["Sí o sí: 非…不可","非…不可 it is imperative that…","","非 A 不可：一定要 A，不能不。","非 A 不可：一定要 A，不能不。","非 A 不可 = es imprescindible A, tiene que ser A.","非 A 不可 = must do A; there's no alternative."],"3-4-6":["Para…: 對…來說","對…來說 as far as...is concerned, for","对…来说 as far as...is concerned, for","對＋人＋來說：從某人的角度來看。","对＋人＋来说：从某人的角度来看。","對 X 來說 = para X, desde la perspectiva de X.","對 X 來說 = for X, from X's point of view."],"3-4-7":["Ser exigente: 講究","對…講究 to be discerning, discriminating, particular about","对…讲究 to be discerning, discriminating, particular about","對＋事情＋很講究：對這件事要求很高、很在意。","对＋事情＋很讲究：对这件事要求很高、很在意。","對 X 很講究 = ser exigente o cuidadoso con X.","對 X 很講究 = to be particular or demanding about X."],"3-5-0":["Lleno de: V滿","Verb Plus Complement V+滿 crowded with","Verb Plus Complement V+满 crowded with","動詞＋滿：空間被填滿了。","动词＋满：空间被填满了。","V + 滿 = llenar: el espacio queda lleno.","Verb + 滿 = the space gets filled up."],"3-5-1":["Salir/descubrir: V出","Verb Particle 出 to have emerged","","動詞＋出（來）：出現、發現或分辨出來，例如想出、做出、看出。","动词＋出（来）：出现、发现或分辨出来，例如想出、做出、看出。","V + 出 (來) = salir o aparecer; también descubrir o distinguir: 想出, 做出, 看出.","Verb + 出(來) = come out or make out, discover: 想出, 做出, 看出."],"3-5-2":["No tan bueno: 不如","不如 not as good as","","A 不如 B：A 沒有 B 好。","A 不如 B：A 没有 B 好。","A 不如 B = A no es tan bueno como B (B es mejor).","A 不如 B = A is not as good as B."],"3-5-3":["Si no…ya: 再不…就…了","Urgent Conditional with 再不…就…了","","再不 A 就 B 了：如果現在還不做 A，馬上就會出問題，有急迫的感覺。","再不 A 就 B 了：如果现在还不做 A，马上就会出问题，有急迫的感觉。","再不 A 就 B 了 = si no hacemos A ya, ocurrirá B (urgencia).","再不 A 就 B 了 = if we don't do A now, B will happen (urgency)."],"3-5-4":["Quitar: V掉","Verb Particle 掉 separated from","","動詞＋掉：去掉、消失、失去，例如丟掉、吃掉、忘掉。","动词＋掉：去掉、消失、失去，例如丢掉、吃掉、忘掉。","V + 掉 = quitar, eliminar o perder: 丟掉, 吃掉, 忘掉.","Verb + 掉 = get rid of, away, lose: 丟掉, 吃掉, 忘掉."],"3-5-5":["¡Increíble!: 居然","居然 to one’s surprise","","居然：沒想到，帶有驚訝的語氣。","居然：没想到，带有惊讶的语气。","居然 = increíblemente, ¡quién lo diría! (sorpresa).","居然 = unexpectedly, surprisingly (expresses surprise)."],"3-5-6":["Ya que: 既然…就","Concession with 既然…（就）… since…(then)…","","既然 A，（就）B：A 已經是事實，所以接著 B。","既然 A，（就）B：A 已经是事实，所以接着 B。","既然 A (就) B = ya que A, entonces B (A es un hecho aceptado).","既然 A，(就) B = since A is already the case, then B."],"3-5-7":["No parar: V個不停","V+個不停 keep on…","V+个不停 keep on…","動詞＋個不停：一直做，停不下來。","动词＋个不停：一直做，停不下来。","V + 個不停 = no parar de hacer algo.","Verb + 個不停 = keep doing, can't stop."],"3-6-0":["Justo por: 因為…才","因為…才… only because…","因为…才… only because…","因為 A 才 B：正是因為 A，所以 B 才會發生。","因为 A 才 B：正是因为 A，所以 B 才会发生。","因為 A 才 B = justamente por A es que B.","因為 A 才 B = it's precisely because of A that B happens."],"3-6-1":["Y encima: …不說，…也…","Complaining with …S1…不說，S2 也… not merely, but also","Complaining with …S1…不说，S2 也… not merely, but also","S1 不說，S2 也…：除了前面那件事，後面還有另一件，常用來抱怨。","S1 不说，S2 也…：除了前面那件事，后面还有另一件，常用来抱怨。","S1 … 不說，S2 也… = no solo S1, además S2 (para quejarse de algo que se suma).","S1 …不說，S2 也… = not to mention S1, S2 too (used to complain)."],"3-6-2":["Sumado a: 再加上","再加上 furthermore","","再加上：再多加一個原因。","再加上：再多加一个原因。","再加上 = sumado a, además. Añade otra razón.","再加上 = on top of that, adds another reason."],"3-6-3":["De todo, pero: 什麼都…就是","什麼都…，就是… everything but …","什么都…，就是… everything but …","什麼都 A，就是 B：什麼都可以，只有 B 例外。","什么都 A，就是 B：什么都可以，只有 B 例外。","什麼都 A，就是 B = de todo A, pero no B.","什麼都 A，就是 B = anything is fine, except B."],"3-6-4":["Preferir…: 寧可…也要","寧可…也要… would rather…, in order to…","宁可…也要… would rather…, in order to…","寧可 A 也要 B：願意犧牲 A，也一定要做到 B。","宁可 A 也要 B：愿意牺牲 A，也一定要做到 B。","寧可 A 也要 B = preferir A antes que renunciar a B (sacrificio).","寧可 A 也要 B = would rather give up A than not get B."],"3-6-5":["Como…: 像…的+N","像…的+noun such (nouns) as","","像 X 的 N：用 X 當例子說明這一類東西。","像 X 的 N：用 X 当例子说明这一类东西。","像 X 的 N = N como X (da ejemplos de una categoría).","像 X 的 N = N such as X (X gives examples of the category)."],"3-6-6":["Por un lado: 一方面…","一方面…，一方面… on the one hand, …, on the other","","一方面 A，一方面 B：同時有兩件事或兩個角度。","一方面 A，一方面 B：同时有两件事或两个角度。","一方面 A，一方面 B = por un lado A, por otro lado B.","一方面 A，一方面 B = on the one hand A, on the other hand B."],"3-6-7":["A medida que: 隨著","隨著 S1…，S2 也… as a consequence of…","随着 S1…，S2 也… as a consequence of…","隨著 X，Y 也…：X 改變時，Y 跟著改變。","随着 X，Y 也…：X 改变时，Y 跟着改变。","隨著 X，Y 也… = a medida que X, Y también…","隨著 X，Y 也… = as X changes, Y changes too."],"3-7-0":["Sin cuidado: 亂+V","亂＋V to do something in an irresponsible manner,","乱＋V to do something in an irresponsible manner,","亂＋動詞：沒有規矩、沒有秩序地做某件事。","乱＋动词：没有规矩、没有秩序地做某件事。","亂 + verbo = hacer algo sin orden ni cuidado.","亂 + verb = do something carelessly or without order."],"3-7-1":["Cada uno: 各V各的","各 V 各的 each doing her/his own…","","各 V 各的：大家各做各的事，互不相干。","各 V 各的：大家各做各的事，互不相干。","各 V 各的 = cada uno hace lo suyo.","各 V 各的 = everyone does their own thing."],"3-7-2":["Aunque: 就算…也","就算…，也… even if…(S1) …, would…(S2)…","","就算 A，也 B：假設 A 發生，結果還是 B。","就算 A，也 B：假设 A 发生，结果还是 B。","就算 A，也 B = aunque A (hipótesis), igual B.","就算 A，也 B = even if A happens, B still holds."],"3-7-3":["Debido a: 因為+N","因為 NP，S… because of NP, S…","因为 NP，S… because of NP, S…","因為＋名詞，句子：說明原因是某個事物，不是一個句子。","因为＋名词，句子：说明原因是某个事物，不是一个句子。","因為 + sustantivo，S… = debido a + sustantivo.","因為 + noun, clause = because of a noun (not a full clause)."],"3-7-4":["Primero…segundo: 一來…二來","一來…，二來… on the one hand…, and on the other…; first…, second…","一来…，二来… on the one hand…, and on the other…; first…, second…","一來 A，二來 B：列出兩個理由。","一来 A，二来 B：列出两个理由。","一來 A，二來 B = primero A, segundo B (enumera razones).","一來 A，二來 B = first A, second B (lists two reasons)."],"3-7-5":["De un lado a otro: V來V去","Repetitively, Back and Forth with V 來 V 去","Repetitively, Back and Forth with V 来 V 去","V 來 V 去：同一個動作來回做，或一直重複。","V 来 V 去：同一个动作来回做，或一直重复。","V 來 V 去 = hacer algo de aquí para allá o una y otra vez.","V 來 V 去 = do the same action back and forth, or over and over."],"3-7-6":["Ya no: 不再…了","不再…了 not…any more","","不再＋動詞＋了：以前會做，現在不做了。","不再＋动词＋了：以前会做，现在不做了。","不再 + verbo + 了 = ya no (algo que antes sí se hacía).","不再 + verb + 了 = no longer (used to, but not anymore)."],"3-8-0":["O…o: 不是…就是","不是…就是… if it's not…, then it’s…","","不是 A 就是 B：只有這兩種可能。","不是 A 就是 B：只有这两种可能。","不是 A 就是 B = o bien A o bien B.","不是 A 就是 B = it's either A or B."],"3-8-1":["Olvídalo: 算了","算了 forget it, drop it","","算了：不再想了、放棄、不計較。","算了：不再想了、放弃、不计较。","算了 = déjalo, olvídalo (dejar pasar o renunciar).","算了 = forget it, drop it, let it go."],"3-8-2":["Así que: 這樣一來","這樣一來 that being the case, that way","这样一来 that being the case, that way","這樣一來：這樣的話，接著會出現某個結果。","这样一来：这样的话，接着会出现某个结果。","這樣一來 = de esta manera, en ese caso (introduce la consecuencia).","這樣一來 = in that case, this way (introduces a consequence)."],"3-8-3":["Ya hace tiempo: 早就…了","早就…了 long since…","","早就＋動詞＋了：很久以前就已經…。","早就＋动词＋了：很久以前就已经…。","早就 + verbo + 了 = hace mucho que ya…","早就 + verb + 了 = already a long time ago."],"3-8-4":["A partir de: 從…起","從…起 starting from…","从…起 starting from…","從＋時間或地點＋起：從那裡開始算。","从＋时间或地点＋起：从那里开始算。","從 + tiempo / lugar + 起 = a partir de.","從 + time/place + 起 = starting from."],"3-8-5":["Sin embargo: 卻","卻 however","却 however","卻：前後意思相反，有「沒想到」的感覺，放在動詞前面。","却：前后意思相反，有「没想到」的感觉，放在动词前面。","卻 = sin embargo, en cambio (contraste inesperado). Va antes del verbo.","卻 = but, however (contrary to expectation), placed before the verb."],"3-8-6":["Por…: 因為…而…","因為…而… therefore, consequently","因为…而… therefore, consequently","因為 X 而 V：因為 X，所以 V，比較書面。","因为 X 而 V：因为 X，所以 V，比较书面。","因為 X 而 V = por X, (resulta) V. Es una forma más escrita.","因為 X 而 V = because of X, V happens (more literary)."],"3-8-7":["Tras: 經過","經過 after","经过 after","經過：走過某個地方，或是經歷一段過程、一段時間之後。","经过：走过某个地方，或是经历一段过程、一段时间之后。","經過 = pasar por (un lugar) o tras (un proceso o tiempo).","經過 = pass through a place, or after going through a process or period of time."],"3-9-0":["Depender de: 靠","靠 to rely on, by means of","","靠：依賴、憑著某個人或某件事。","靠：依赖、凭着某个人或某件事。","靠 = depender de, apoyarse en.","靠 = rely on, depend on."],"3-9-1":["Tanto…como: 既…又","既…又… not merely…, but…as well","","既 A 又 B：同時有兩個特點，比「又…又…」更書面。","既 A 又 B：同时有两个特点，比「又…又…」更书面。","既 A 又 B = tanto A como B (dos cualidades; más formal que 又…又…).","既 A 又 B = both A and B (two qualities; more formal than 又…又…)."],"3-9-2":["Dentro de: 以內","…以內 within …","…以内 within …","以內：不超過某個範圍（數量、時間、空間）。","以内：不超过某个范围（数量、时间、空间）。","以內 = dentro de (un límite de cantidad, tiempo o espacio).","以內 = within (a limit of quantity, time or space)."],"3-9-3":["Representar: 占","占 to constitute","","占：佔有某個比例或空間。","占：占有某个比例或空间。","占 = ocupar o representar (una parte o porcentaje).","占 = to take up or make up (a proportion or space)."],"3-9-4":["En cuanto a: (在)…上","（在） NP 上 regarding NP","","（在）＋名詞＋上：在某方面、就某件事來說。","（在）＋名词＋上：在某方面、就某件事来说。","(在) N 上 = en el aspecto de N, en cuanto a N.","(在) N 上 = in the area of N, regarding N."],"3-9-5":["Traer a: 給…帶來","給…帶來 to bring… to…","给…带来 to bring… to…","給 A 帶來 B：對 A 產生 B 這個影響。","给 A 带来 B：对 A 产生 B 这个影响。","給 A 帶來 B = traerle B a A (efecto o consecuencia).","給 A 帶來 B = bring B to A (an effect or consequence)."],"3-9-6":["Al final: 結果","結果 consequently, in the end","结果 consequently, in the end","結果：最後的結局，常和預期不同。","结果：最后的结局，常和预期不同。","結果 = el resultado fue…, al final (el desenlace de algo).","結果 = in the end, the outcome (often unexpected)."],"3-10-0":["En cuanto a: 至於","Introducing a New Topic with 至於…, as to, as far","Introducing a New Topic with 至于…, as to, as far","至於：換一個話題，意思是「說到…的話」。","至于：换一个话题，意思是「说到…的话」。","至於 = en cuanto a… (cambia a otro tema).","至於 = as for (switches to another topic)."],"3-10-1":["Depende de: A看B","看 depends on","","A 看 B：A 要看 B 的情況才能決定。","A 看 B：A 要看 B 的情况才能决定。","A 看 B = A depende de B.","A 看 B = A depends on B."],"3-10-2":["Siempre: 一向","一向 all along, has always…","","一向：從以前到現在都是這樣，已成習慣。","一向：从以前到现在都是这样，已成习惯。","一向 = siempre (desde antes hasta ahora, como hábito).","一向 = always, all along (from before until now, as a habit)."],"3-10-3":["Por ejemplo: 拿…來說","拿…來說 take…as an example","拿…来说 take…as an example","拿 X 來說：用 X 當例子來說明。","拿 X 来说：用 X 当例子来说明。","拿 X 來說 = tomando X como ejemplo.","拿 X 來說 = take X as an example."],"3-10-4":["Pasiva formal: 受","Passive Sentences with 受","","受＋名詞：受到歡迎、受傷、受影響，比「被」更書面。","受＋名词：受到欢迎、受伤、受影响，比「被」更书面。","受 + sustantivo: 受到歡迎 (ser bien recibido), 受傷 (herirse), 受影響 (ser afectado). Pasiva de estilo más formal.","受 + noun: 受到歡迎 (be welcomed), 受傷 (get hurt), 受影響 (be affected); a more formal passive."],"3-10-5":["Por cualquier cosa: 動不動就","動不動就… to do something impetuously","动不动就… to do something impetuously","動不動就＋動詞：一點小事就會…，多用在不好的行為。","动不动就＋动词：一点小事就会…，多用在不好的行为。","動不動就 + verbo = a la menor ocasión, por cualquier cosa (negativo).","動不動就 + verb = at the slightest thing; usually negative behavior."],"3-11-0":["En realidad: 到底","到底 after all? how on earth…?","","到底：用在問句，想問出真正的答案；也有「畢竟」的意思。","到底：用在问句，想问出真正的答案；也有「毕竟」的意思。","到底 = en realidad, ¿qué demonios…? Insiste en una pregunta.","到底 = on earth, exactly (presses a question); also 'after all'."],"3-11-1":["Incluso: 甚至","甚至 even","","甚至：連…也，說到更極端的情況。","甚至：连…也，说到更极端的情况。","甚至 = incluso, hasta (el caso extremo).","甚至 = even (points to an extreme case)."],"3-11-2":["Entonces: 這麼說","這麼說 that being the case, in that case","这么说 that being the case, in that case","這麼說：根據對方說的話，得出一個結論。","这么说：根据对方说的话，得出一个结论。","這麼說 = entonces, siendo así… (se concluye a partir de lo que dijo el otro).","這麼說 = in that case, so (drawing a conclusion from what was just said)."],"3-11-3":["Relacionado con: 跟B有關的A","跟 B 有關的 A A is related to B","跟 B 有关的 A A is related to B","跟 B 有關的 A：和 B 有關係的 A。","跟 B 有关的 A：和 B 有关系的 A。","跟 B 有關的 A = A relacionado con B.","跟 B 有關的 A = A that is related to B."],"3-11-4":["No hay remedio: 不得不","不得不 have no choice but to","","不得不＋動詞：因為情況，沒有別的選擇。","不得不＋动词：因为情况，没有别的选择。","不得不 + verbo = no tener más remedio que, verse obligado a.","不得不 + verb = have no choice but to, forced by circumstances."],"3-11-5":["Así como: 以及","以及 as well as","","以及：「和」的書面說法，連接名詞。","以及：「和」的书面说法，连接名词。","以及 = así como. Une sustantivos (más formal).","以及 = as well as (a more formal 'and', linking nouns)."],"3-12-0":["Solo…: 只不過","只不過… (而已) merely…; nothing more than…","只不过… (而已) merely…; nothing more than…","只不過…（而已）：只是…，沒有那麼嚴重或特別。","只不过…（而已）：只是…，没有那么严重或特别。","只不過…(而已) = simplemente, no es más que…","只不過…(而已) = merely, nothing more than."],"3-12-1":["A cargo de: 由","Introducing an Agent with 由","","由＋人或單位＋動詞：說明由誰負責做。","由＋人或单位＋动词：说明由谁负责做。","由 + agente + verbo = a cargo de, por parte de (quien hace algo).","由 + person/unit + verb = to be done by, in charge of."],"3-12-2":["¿Acaso…?: 難道","難道… how could it possibly be true","难道… how could it possibly be true","難道…嗎？：反問句，意思是「不可能吧」。","难道…吗？：反问句，意思是「不可能吧」。","難道…嗎？ = ¿acaso…? Pregunta retórica.","難道…嗎？ = a rhetorical question: 'surely not?'."],"3-12-3":["Lleno: 滿","To Reach a Ceiling with 滿","To Reach a Ceiling with 满","滿：到最多了，不能再多，例如客滿、額滿、坐滿。","满：到最多了，不能再多，例如客满、额满、坐满。","滿 = llegar al máximo, estar lleno: 客滿, 額滿, 坐滿.","滿 = full to the maximum: 客滿, 額滿, 坐滿."],"3-12-4":["Por/para: 為","Beneficiary marker 為","Beneficiary marker 为","為＋對象＋動詞：替誰、為了誰做某件事。","为＋对象＋动词：替谁、为了谁做某件事。","為 + beneficiario + verbo = por / para (a favor de).","為 + beneficiary + verb = do something for someone."],"3-12-5":["En el aspecto: (在)…方面","（在）…方面 with respect to; regarding","","（在）＋名詞＋方面：就某個方面來說。","（在）＋名词＋方面：就某个方面来说。","(在) X 方面 = en el aspecto de X, con respecto a X.","(在) X 方面 = in terms of X, with respect to X."],"4-1-0":["Mejor B que A: 與其…不如","與其 A…不如 B… B rather than A","与其 A…不如 B… B rather than A","比較兩個選擇，說明第二個比較好。「與其 A，不如 B」是「與其做 A，還不如做 B」的意思。","比较两个选择，说明第二个比较好。「与其 A，不如 B」是「与其做 A，还不如做 B」的意思。","與其 A，不如 B = en vez de A, es mejor B. Se compara dos opciones y se recomienda la segunda.","Compares two options and says the second is better. 與其 A，不如 B means 'rather than A, it would be better to B'."],"4-1-1":["Contraste con 就","就 on the contrary","","別人的想法或情況是一樣的，但說話的人（或這個人）卻不同，這時可以用「就」表示對比，意思像「卻」「反倒」。","别人的想法或情况是一样的，但说话的人（或这个人）却不同，这时可以用「就」表示对比，意思像「却」「反倒」。","就 puede marcar un contraste inesperado: «en cambio, sin embargo». Los demás piensan una cosa y esta persona piensa lo contrario.","When others think or do one thing but this person differs, 就 marks the contrast, much like 'whereas' or 'on the contrary'."],"4-1-2":["Usos de 就 (resumen)","A Summary of the Various Usages of 就","","「就」常見的用法有：一、很快、馬上（我馬上就到）；二、強調「正是」（這就是……）；三、只有（就我一個人）；四、前後連接（要是……就……）。","「就」常见的用法有：一、很快、马上（我马上就到）；二、强调「正是」（这就是……）；三、只有（就我一个人）；四、前后连接（要是……就……）。","Resumen de 就: (1) enseguida, pronto; (2) enfático, «precisamente»; (3) «solo», limita una cantidad; (4) condición y resultado (要是…就…).","Main uses of 就: (1) soon, right away; (2) emphatic 'precisely'; (3) 'only'; (4) linking condition and result (要是…就…)."],"4-1-3":["Ni A, ni B: 別說…就是","別說 A，就是 B 也… never mind A, even B is the case…","别说 A，就是 B 也… never mind A, even B is the case…","先說一件比較難的事（A）都不行，連比較容易的事（B）也不行。意思是「連 B 都……，更不用說 A」。","先说一件比较难的事（A）都不行，连比较容易的事（B）也不行。意思是「连 B 都……，更不用说 A」。","別說 A，就是 B 也… = ni hablar de A; incluso B (el caso más fácil) también…. A es el caso más difícil y B el más fácil.","First name the harder thing (A), then say even the easier thing (B) isn't possible either: 'forget A, even B…'."],"4-1-4":["Prácticamente: 簡直","簡直 to put it simply and plainly, it seems as if","简直 to put it simply and plainly, it seems as if","「簡直」用來誇張地描述，意思是「幾乎就是」「根本就像」，可以表示讚美，也可以表示抱怨。","「简直」用来夸张地描述，意思是「几乎就是」「根本就像」，可以表示赞美，也可以表示抱怨。","簡直 = es simplemente…, casi como si… Exagera para dar énfasis (admiración o queja).","簡直 exaggerates for emphasis: 'it's practically…', 'it's simply like…'. It can express admiration or complaint."],"4-1-5":["No llega a tanto: 不至於","不至於 but the situation would not be so bad as to …","不至于 but the situation would not be so bad as to …","「不至於」表示事情不會嚴重到那個地步，用來否定一個太誇張的想法。","「不至于」表示事情不会严重到那个地步，用来否定一个太夸张的想法。","不至於 = no llega al punto de…, no sería tan grave. Sirve para descartar una posibilidad exagerada.","不至於 says things won't go as far as that; it's used to rule out an exaggerated possibility."],"4-1-6":["Por lo general: 往往","往往 usually, tend to","","「往往」表示照過去的經驗，常常是這樣，有規律性。不能用在未來，也不能用在只發生一次的事。","「往往」表示照过去的经验，常常是这样，有规律性。不能用在未来，也不能用在只发生一次的事。","往往 = por lo general, suele (patrón habitual basado en la experiencia). No se usa para el futuro ni para hechos únicos.","往往 describes what usually happens based on experience. It isn't used for the future or for one-time events."],"4-1-7":["Por diversión: V 著玩","Do Something Just for Fun V 著玩","Do Something Just for Fun V 着玩","「V 著玩」表示只是為了好玩去做，不是認真的。","「V 着玩」表示只是为了好玩去做，不是认真的。","V 著玩 = hacer algo solo por diversión, sin tomarlo en serio.","V 著玩 means doing something just for fun, not seriously."],"4-2-0":["Lograr algo: V 成","Verb Complement 成 successful(ly)","","「V＋成」表示事情做成了、成功了。否定用「V 不成」，表示沒辦法完成。","「V＋成」表示事情做成了、成功了。否定用「V 不成」，表示没办法完成。","V + 成 = lograr hacer algo (resultado exitoso). Negación: V 不成 = no se logró.","V + 成 shows that something was achieved successfully. Its negative, V 不成, means it couldn't be done."],"4-2-1":["Por si acaso: 萬一","萬一 supposing, in the event of something negative","万一 supposing, in the event of something negative","「萬一」用在可能性很小、但如果發生會很糟的事情，意思是「如果真的……」。","「万一」用在可能性很小、但如果发生会很糟的事情，意思是「如果真的……」。","萬一 = en caso de que (algo malo y poco probable), por si acaso.","萬一 introduces something unlikely but bad if it happened: 'in case…', 'what if…'."],"4-2-2":["Creer erróneamente: 以為","以為 to have wrongly thought that…","以为 to have wrongly thought that…","「以為」是自己想的跟事實不一樣，後來才發現弄錯了。","「以为」是自己想的跟事实不一样，后来才发现弄错了。","以為 = creer (equivocadamente) que…; la realidad resultó ser distinta.","以為 means you thought something that turned out to be wrong."],"4-2-3":["El adverbio 可","Adverb 可","","「可」放在動詞或形容詞前面加強語氣，常用在提醒、警告或感嘆，是口語的說法。","「可」放在动词或形容词前面加强语气，常用在提醒、警告或感叹，是口语的说法。","可 como adverbio da énfasis: «sí que», «de verdad». Se usa en advertencias, exclamaciones y lenguaje coloquial.","The adverb 可 adds emphasis before a verb or adjective, often in reminders, warnings or exclamations. It's colloquial."],"4-2-4":["Para evitar que: 免得","免得 lest, so as to avoid","","「免得」放在後面的句子，表示為了避免不好的結果，所以前面先做某件事。","「免得」放在后面的句子，表示为了避免不好的结果，所以前面先做某件事。","免得 = para evitar que, no sea que. Introduce la consecuencia no deseada y va en la segunda cláusula.","免得 goes in the second clause: you do something first so as to avoid an unwanted result."],"4-2-5":["Alguna vez: 曾經","曾經 experience in the past, V’ed before","曾经 experience in the past, V’ed before","「曾經」表示過去有過某種經驗，現在已經不是這樣了，常常跟「過」一起用。","「曾经」表示过去有过某种经验，现在已经不是这样了，常常跟「过」一起用。","曾經 + V = alguna vez, en el pasado (una experiencia que ya no continúa). Suele ir con 過.","曾經 shows that something happened in the past and no longer holds now. It often appears with 過."],"4-2-6":["Etcétera: 等","Enumeration Particle 等 etc…","","列舉幾個例子後加上「等」，表示還有其他沒說完的，也可以說「等等」。","列举几个例子后加上「等」，表示还有其他没说完的，也可以说「等等」。","等 al final de una lista = etcétera; indica que hay más ejemplos. También se dice 等等.","Add 等 after a list of examples to show there are more; 等等 also works."],"4-2-7":["Lo que…: 所 + verbo","Making a Verb with the Particle 所","","「所」加在動詞前面，可以把一個動作變成名詞性的說法，意思是「……的（事／東西）」，比較書面。","「所」加在动词前面，可以把一个动作变成名词性的说法，意思是「……的（事／东西）」，比较书面。","所 + verbo forma una expresión nominal de estilo formal: «lo que…». Ejemplos: 我所知道的, 他所說的.","所 before a verb turns it into a noun-like phrase meaning 'what…' or 'that which…'. It's fairly formal."],"4-3-0":["¿Para qué? 何必","何必 why must","","「何必」是反問，意思是「不需要」「沒有必要」，常用來勸人不要這樣做。","「何必」是反问，意思是「不需要」「没有必要」，常用来劝人不要这样做。","何必 = ¿para qué…?, ¿por qué habrías de…? Es una pregunta retórica: no hace falta.","何必 is a rhetorical question meaning 'there's no need to…', often used to persuade someone not to do something."],"4-3-1":["No necesariamente: 不見得","不見得 not necessarily","不见得 not necessarily","「不見得」表示不一定，不一定是你想的那樣，語氣比較委婉。","「不见得」表示不一定，不一定是你想的那样，语气比较委婉。","不見得 = no necesariamente. Niega de forma suave que algo sea siempre así.","不見得 means 'not necessarily'. It's a mild way to say it isn't always as you think."],"4-3-2":["La partícula 嘛","嘛 isn’t it obvious that","","「嘛」放在句尾，表示這件事很明顯、很簡單，或帶一點勸說、不耐煩的語氣，是口語的說法。","「嘛」放在句尾，表示这件事很明显、很简单，或带一点劝说、不耐烦的语气，是口语的说法。","嘛 al final de la oración es una partícula coloquial: indica que algo es obvio o insiste con un tono de reproche suave.","嘛 at the end of a sentence shows that something is obvious, or adds a gently persuasive or impatient tone. It's colloquial."],"4-3-3":["Acostumbrarse: V 慣","Verb Particle 慣","Verb Particle 惯","「V＋慣」表示習慣了，例如「吃慣」「住慣」「用慣」。否定的「看不慣」是「看了不舒服、無法接受」。","「V＋惯」表示习惯了，例如「吃惯」「住惯」「用惯」。否定的「看不惯」是「看了不舒服、无法接受」。","V + 慣 = estar acostumbrado a: 吃慣, 住慣, 用慣. En negativo, 看不慣 = no soportar ver algo.","V + 慣 means being used to something (吃慣, 住慣, 用慣). 看不慣 means you can't stand seeing it."],"4-3-4":["No tener fuerzas: V 得動／不動","Verb Complement 動 capable of causing movement","Verb Complement 动 capable of causing movement","「V＋得動／不動」表示有沒有力氣把一個動作做完，例如「搬不動」「走不動」「吃不動」。","「V＋得动／不动」表示有没有力气把一个动作做完，例如「搬不动」「走不动」「吃不动」。","V + 得動 / 不動 = tener / no tener fuerza para mover o hacer algo: 搬不動, 走不動, 吃不動.","V + 得動 / 不動 shows whether you have the strength to do something, like 搬不動, 走不動, 吃不動."],"4-3-5":["Sin darse cuenta: 無形中","無形中 without knowing it, and before you know it","无形中 without knowing it, and before you know it","「無形中」表示不知不覺、慢慢地發生，自己沒有特別注意到。","「无形中」表示不知不觉、慢慢地发生，自己没有特别注意到。","無形中 = sin darse cuenta, de forma imperceptible y poco a poco.","無形中 means something happens imperceptibly and gradually, without you noticing."],"4-3-6":["Además: 此外","此外 in addition, furthermore","","「此外」是書面的連接詞，意思是「除了這個以外，還有……」，用來再加一點。","「此外」是书面的连接词，意思是「除了这个以外，还有……」，用来再加一点。","此外 = además, aparte de esto. Es un conector de estilo formal que añade otro punto.","此外 is a formal connector meaning 'besides this, there is also…'; it adds another point."],"4-3-7":["En resumen: 總而言之","總而言之 in short","总而言之 in short","「總而言之」用在說完幾個看法之後，引出簡短的結論。","「总而言之」用在说完几个看法之后，引出简短的结论。","總而言之 = en resumen, en una palabra. Introduce la conclusión.","總而言之 introduces a brief conclusion after several points have been made."],"4-4-0":["Por fin: 總算","總算 finally, speaking roughly (in the ball park)","总算 finally, speaking roughly (in the ball park)","「總算」表示等了很久或努力很久之後，終於有了結果，帶著鬆了一口氣的感覺。","「总算」表示等了很久或努力很久之后，终于有了结果，带着松了一口气的感觉。","總算 = por fin, finalmente. Expresa alivio después de esperar o esforzarse mucho.","總算 shows that after a long wait or effort, a result finally came, with a sense of relief."],"4-4-1":["No es más que…: 還不就是","還不就是 nothing more than","还不就是 nothing more than","「還不就是」用來說「也不過是……」，把事情說得不重要，是口語的反問。","「还不就是」用来说「也不过是……」，把事情说得不重要，是口语的反问。","還不就是 = no es más que…, al fin y al cabo es solo… Resta importancia; tono coloquial.","還不就是 is a colloquial rhetorical phrase meaning 'it's nothing more than…', playing down how important something is."],"4-4-2":["Negación fuerte con 才","Outright Denial with 才","","「才不」「才沒有」用來強烈反駁，意思是「才不是這樣」「我才不要」。","「才不」「才没有」用来强烈反驳，意思是「才不是这样」「我才不要」。","才 enfático con negación: «eso sí que no», «claro que no». Contradice con fuerza lo que se dijo: 才不, 才沒有.","才不 / 才沒有 strongly denies or pushes back: 'no way', 'certainly not'."],"4-4-3":["Usos de 才 (resumen)","A Summary of the Various Usages of 才","","「才」常見的用法有：一、做完某件事之後才能……；二、數量很少（才八點）；三、比預期晚（十點才來）；四、強烈否定（我才不去）。","「才」常见的用法有：一、做完某件事之后才能……；二、数量很少（才八点）；三、比预期晚（十点才来）；四、强烈否定（我才不去）。","Resumen de 才: (1) «solo entonces» (condición previa); (2) «apenas» (cantidad pequeña); (3) más tarde de lo esperado; (4) negación enfática (我才不去).","Main uses of 才: (1) only after something is done; (2) 'only/just' for small amounts; (3) later than expected; (4) emphatic denial."],"4-4-4":["Definir: 所謂…是指","所謂（的） A 是指 B so called A refers to B","所谓（的） A 是指 B so called A refers to B","用來解釋一個詞的意思：「所謂 A」就是「大家說的 A」，後面接「是指 B」說明它是什麼。","用来解释一个词的意思：「所谓 A」就是「大家说的 A」，后面接「是指 B」说明它是什么。","所謂（的）A，是指 B = lo que se llama A se refiere a B. Sirve para definir un término.","Used to define a term: 所謂 A means 'what is called A', followed by 是指 B to say what it refers to."],"4-4-5":["De un tirón: 一口氣","一口氣 lit. in one breath","一口气 lit. in one breath","「一口氣」表示一次就做完，中間不停，不休息。","「一口气」表示一次就做完，中间不停，不休息。","一口氣 = de un tirón, sin parar (en una sola respiración).","一口氣 means doing something in one go, without stopping or resting."],"4-4-6":["Solo A ya…: 光 A 就","光 A 就… just A alone…","","「光 A 就……」表示只算 A 這一項，就已經很多了，更不用算別的。","「光 A 就……」表示只算 A 这一项，就已经很多了，更不用算别的。","光 A 就… = solo A ya… Solo eso ya es mucho, sin contar lo demás.","光 A 就… means that A alone is already a lot, without counting anything else."],"4-4-7":["Queja con 都","Expressing Displeasure or Annoyance with 都","","「都是你……」表示責怪，說因為你才會這樣；「都＋時間＋了」表示已經這麼晚了，還沒做某件事。","「都是你……」表示责怪，说因为你才会这样；「都＋时间＋了」表示已经这么晚了，还没做某件事。","都 + causa o tiempo expresa queja o fastidio: 都是你… = es todo culpa tuya; 都 + hora + 了 = ya es tan tarde y todavía….","都是你… blames someone ('it's all your fault'); 都 + time + 了 means 'it's already this late, and yet…'."],"4-5-0":["Pregunta retórica: 哪裡","Rhetorical Question with 哪裡","Rhetorical Question with 哪里","「哪裡」放在動詞或形容詞前面，用反問的方式表示否定，意思是「怎麼會」「才不是」。回答別人稱讚時說「哪裡哪裡」，是謙虛的說法。","「哪里」放在动词或形容词前面，用反问的方式表示否定，意思是「怎么会」「才不是」。回答别人称赞时说「哪里哪里」，是谦虚的说法。","哪裡 + verbo / adjetivo = negación retórica: «qué va», «cómo voy a…». También se usa como respuesta modesta a un halago.","哪裡 before a verb or adjective makes a rhetorical negation: 'how could…', 'not at all'. Replying 哪裡 to a compliment is a modest answer."],"4-5-1":["Al fin y al cabo: 畢竟","畢竟 after all","毕竟 after all","「畢竟」提醒對方最根本的原因，意思是「說到底」「終究」。","「毕竟」提醒对方最根本的原因，意思是「说到底」「终究」。","畢竟 = al fin y al cabo, después de todo. Recuerda la razón de fondo.","畢竟 points to the underlying reason: 'after all', 'when all is said and done'."],"4-5-2":["Efectivamente: 的確","的確 indeed","的确 indeed","「的確」用來確認一件事是真的，意思是「確實」。","「的确」用来确认一件事是真的，意思是「确实」。","的確 = efectivamente, realmente. Confirma que algo es cierto.","的確 confirms that something is true: 'indeed', 'certainly'."],"4-5-3":["Por otro lado: 話說回來","話說回來 however, on the other hand","话说回来 however, on the other hand","「話說回來」用來轉到另一個角度，或把話題拉回來，意思是「不過」「說回來」。","「话说回来」用来转到另一个角度，或把话题拉回来，意思是「不过」「说回来」。","話說回來 = pero, por otro lado; dicho esto. Introduce otro punto de vista o vuelve al tema.","話說回來 shifts to another angle or brings the topic back: 'that said', 'on the other hand'."],"4-5-4":["La razón es…: 之所以…是因為","NP 之所以 S2 是因為 S1 S2 is due to S1","NP 之所以 S2 是因为 S1 S2 is due to S1","先說結果，再說原因：「之所以……，是因為……」。比「因為……所以……」更強調原因。","先说结果，再说原因：「之所以……，是因为……」。比「因为……所以……」更强调原因。","NP 之所以 S2，是因為 S1 = la razón por la que S2 es que S1. Primero se dice el resultado y luego la causa.","State the result first, then the cause: 之所以…，是因為…. It puts more weight on the reason than 因為…所以…."],"4-5-5":["En absoluto: 根本","根本 not…at all","","「根本」放在否定的句子裡，表示完全不是這樣，意思是「從來就不」「完全不」。","「根本」放在否定的句子里，表示完全不是这样，意思是「从来就不」「完全不」。","根本 + negación = en absoluto, de ninguna manera. Enfatiza que no es así desde el fondo.","根本 in a negative sentence means 'not at all', 'not even in the slightest'."],"4-5-6":["Y mucho menos: 更別說…了","更別說…了 let alone, never mind","更别说…了 let alone, never mind","先說一件比較容易的事都做不到，再說「更別說 A 了」，表示更難的事當然做不到。","先说一件比较容易的事都做不到，再说「更别说 A 了」，表示更难的事当然做不到。","更別說 A 了 = y mucho menos A, ni hablar de A. Se niega un caso más difícil después de uno más fácil.","After saying someone can't even do the easier thing, 更別說 A 了 adds that the harder thing is out of the question."],"4-5-7":["Desear con fuerza: 恨不得","恨不得 one really wishes one could…","","「恨不得」表示非常想做某件事，但通常做不到。","「恨不得」表示非常想做某件事，但通常做不到。","恨不得 + verbo = desear con todas las fuerzas poder hacer algo (a menudo imposible).","恨不得 means desperately wanting to do something, usually something you can't actually do."],"4-6-0":["¿Por qué tan…? 怎麼這麼","怎麼這麼 Why so…?","怎么这么 Why so…?","「怎麼這麼＋形容詞／動詞」表示驚訝或抱怨，意思是「為什麼這麼……」。","「怎么这么＋形容词／动词」表示惊讶或抱怨，意思是「为什么这么……」。","怎麼這麼 + adjetivo / verbo = ¿por qué tan…? Expresa sorpresa o queja.","怎麼這麼 + adjective / verb expresses surprise or complaint: 'why so…?'."],"4-6-1":["Exclamación con 多","Intensifying Adverb 多 how","","「多＋形容詞」用在感嘆句，意思是「多麼……」，句尾常加「啊」「呀」。","「多＋形容词」用在感叹句，意思是「多么……」，句尾常加「啊」「呀」。","多 + adjetivo en una exclamación = ¡qué…! Suele cerrar con 啊 / 呀 y expresa admiración.","多 + adjective in an exclamation means 'how…!', and often ends with 啊 or 呀."],"4-6-2":["Usos de 多 (resumen)","The Various Functions of 多","","「多」常見的用法有：一、數字後面表示「超過」（三十多歲）；二、問程度（多高）；三、感嘆（多好看）；四、「不管多……」表示「再……也」。","「多」常见的用法有：一、数字后面表示「超过」（三十多岁）；二、问程度（多高）；三、感叹（多好看）；四、「不管多……」表示「再……也」。","Funciones de 多: (1) «más de» después de un número; (2) pregunta de grado (多高, 多久); (3) exclamación «qué…»; (4) «por más… que» en 不管多….","Common uses of 多: (1) 'more than' after a number; (2) asking degree (多高); (3) exclamation 'how…'; (4) 不管多… for 'no matter how…'."],"4-6-3":["En vano: 白","白 in vain, for nothing","","「白＋動詞」表示做了卻沒有結果、沒有用，例如「白跑一趟」。也可以表示「不用付錢」（白吃）。","「白＋动词」表示做了却没有结果、没有用，例如「白跑一趟」。也可以表示「不用付钱」（白吃）。","白 + verbo = en vano, para nada, sin resultado: 白跑一趟 = ir en balde. También puede significar «gratis» (白吃).","白 + verb means doing something with no result, such as 白跑一趟 (a wasted trip). It can also mean 'for free' (白吃)."],"4-6-4":["Siempre: 總是","總是 always","总是 always","「總是」表示一直都是這樣，是固定的習慣，有時帶一點抱怨。","「总是」表示一直都是这样，是固定的习惯，有时带一点抱怨。","總是 = siempre, constantemente. Es un hábito constante, a veces con un tono de queja.","總是 means 'always', a constant habit, sometimes with a slight tone of complaint."],"4-6-5":["V 下來 (resumen)","The Various Meanings of the Verb Complement 下來","The Various Meanings of the Verb Complement 下来","「V＋下來」常見的意思有：一、從上往下；二、把東西記錄或留住（記下來、留下來）；三、從過去持續到現在；四、變安靜、變穩定（安靜下來）。","「V＋下来」常见的意思有：一、从上往下；二、把东西记录或留住（记下来、留下来）；三、从过去持续到现在；四、变安静、变稳定（安静下来）。","V + 下來: (1) de arriba hacia abajo; (2) algo queda registrado o se queda (記下來, 留下來); (3) continuar hasta ahora; (4) calmarse (安靜下來).","Common meanings of V + 下來: (1) downward; (2) recording or keeping something (記下來, 留下來); (3) lasting up to now; (4) calming down."],"4-6-6":["Cuando: 當…的時候","當…的時候 when, while, at the time of","当…的时候 when, while, at the time of","「當＋一段話＋的時候」表示「在……的時間」，比只說「……的時候」稍微正式一點。","「当＋一段话＋的时候」表示「在……的时间」，比只说「……的时候」稍微正式一点。","當 + frase + 的時候 = cuando, mientras, en el momento en que…. 當 hace la expresión un poco más formal.","當 + clause + 的時候 means 'at the time when…'; it's slightly more formal than just …的時候."],"4-6-7":["Al contrario: 反而","反而 on the contrary","","「反而」表示結果和預期相反，意思是「結果卻是」。","「反而」表示结果和预期相反，意思是「结果却是」。","反而 = al contrario, en cambio. El resultado va en contra de lo esperado.","反而 shows that the result is the opposite of what you'd expect: 'on the contrary', 'instead'."],"4-7-0":["Sorpresa con 還","還 to my surprise","还 to my surprise","「還」可以表示事情比想像的更好、更多，帶有一點意外。常見的說法有「還會……」「還有……」。","「还」可以表示事情比想像的更好、更多，带有一点意外。常见的说法有「还会……」「还有……」。","還 expresa sorpresa: algo resulta mejor o más de lo esperado. Suele aparecer en frases como 還會…, 還有….","還 expresses surprise that something is better or more than expected. Common patterns are 還會… and 還有…."],"4-7-1":["Alternar: 一下…一下…","Alternating Events with 一下…一下…","","「一下 A，一下 B」表示兩種情況很快輪流出現，一下子這樣、一下子那樣。","「一下 A，一下 B」表示两种情况很快轮流出现，一下子这样、一下子那样。","一下 A，一下 B = ahora A, ahora B. Describe dos situaciones que se alternan rápidamente.","一下 A, 一下 B means 'one moment A, the next moment B'. Two situations alternate quickly."],"4-7-2":["Fracciones: A 分之 B","Various Fractions with A 分之 B","","說分數時，先說分母（A），再說分子（B），中間加「分之」。百分比用「百分之」。","说分数时，先说分母（A），再说分子（B），中间加「分之」。百分比用「百分之」。","A 分之 B expresa fracciones: se dice primero el denominador (A) y luego el numerador (B). Los porcentajes usan 百分之.","For fractions, say the denominator (A) first, then 分之, then the numerator (B). Percentages use 百分之."],"4-7-3":["Seguidos: 一連","一連 without interruption, in rapid succession","一连 without interruption, in rapid succession","「一連＋數量＋動詞」表示動作連續發生好幾次，或持續好幾天，中間沒有停。","「一连＋数量＋动词」表示动作连续发生好几次，或持续好几天，中间没有停。","一連 + cantidad + verbo = varias veces o durante varios días seguidos, sin interrupción.","一連 + quantity + verb means an action happens several times or for several days in a row, without a break."],"4-7-4":["Hasta saciarse: V 個夠","To Have a Full Dosage of an Activity V 個夠","To Have a Full Dosage of an Activity V 个够","「動詞＋個夠」表示盡情做某件事，做到滿意為止，例如「玩個夠」「吃個夠」「睡個夠」。","「动词＋个够」表示尽情做某件事，做到满意为止，例如「玩个够」「吃个够」「睡个够」。","Verbo + 個夠 = hacer algo hasta quedar satisfecho, a más no poder (玩個夠, 吃個夠, 睡個夠).","Verb + 個夠 means doing something to your heart's content, as in 玩個夠, 吃個夠, 睡個夠."],"4-7-5":["Ayudar a: 有助於","有助於 be conducive to","有助于 be conducive to","「有助於」是「對……有幫助」的比較正式說法，後面接動詞或名詞。","「有助于」是「对……有帮助」的比较正式说法，后面接动词或名词。","有助於 + verbo / sustantivo = ayudar a, ser útil para. Es una forma más formal de 對…有幫助.","有助於 + verb/noun means 'helps with / is conducive to'. It is a more formal way of saying 對…有幫助."],"4-7-6":["Así que: 於是","於是… thus, consequently","于是… thus, consequently","「於是」表示因為前面的事，接著發生了後面的事，意思是「所以就」。前後兩件事有先後順序。","「于是」表示因为前面的事，接着发生了后面的事，意思是「所以就」。前后两件事有先后顺序。","於是 = así que, por eso (en consecuencia). Une dos hechos en orden: el segundo ocurre a causa del primero.","於是 means 'so / as a result'. The second event follows from the first, in order."],"4-7-7":["Hacia, a: 向","向 to, toward","","「向」後面接人或方向，表示動作的對象或方向，例如「向……借」「向……道謝」「向前走」。","「向」后面接人或方向，表示动作的对象或方向，例如「向……借」「向……道谢」「向前走」。","向 + persona o dirección = hacia, a, de. Marca el destinatario de una acción: 向…借, 向…道謝, 向前走.","向 + person or direction marks the target or direction of an action, as in 向…借, 向…道謝, 向前走."],"4-8-0":["De todos modos: 反正","反正 at any rate, anyway","","「反正」表示不管怎麼樣，結果都一樣，所以不用在意或不必再討論。","「反正」表示不管怎么样，结果都一样，所以不用在意或不必再讨论。","反正 = de todos modos, total. Se usa cuando la situación no cambia, haga lo que se haga.","反正 means 'anyway': whatever happens, the result is the same, so there's no need to worry or argue about it."],"4-8-1":["No solo: 不只","不只 not merely, exceeding","","「不只 A，還／也 B」表示除了 A 以外，B 也是，範圍比 A 更大。","「不只 A，还／也 B」表示除了 A 以外，B 也是，范围比 A 更大。","不只 A，還／也 B = no solo A, sino también B. La parte B añade algo más.","不只 A, 還/也 B means 'not only A, but also B'; B adds something beyond A."],"4-8-2":["Inevitable: 難免","難免 inevitably, it is only natural that","难免 inevitably, it is only natural that","「難免」表示在這種情況下，很容易發生某件事，幾乎無法避免。","「难免」表示在这种情况下，很容易发生某件事，几乎无法避免。","難免 = es inevitable, es natural que. Se usa para algo que casi siempre pasa en esa situación.","難免 means 'it's hard to avoid / it's only natural': something is very likely to happen in this situation."],"4-8-3":["Eso sí: 倒是","倒是 on the other hand","","「倒是」表示和前面說的有一點相反或不同，語氣比較輕，意思是「不過……卻……」。","「倒是」表示和前面说的有一点相反或不同，语气比较轻，意思是「不过……却……」。","倒是 = en cambio, eso sí. Introduce un contraste suave con lo anterior.","倒是 introduces a mild contrast with what came before: 'but, on the other hand'."],"4-8-4":["Ahora sí: 這下子","這下子 that being the case, as a consequence","这下子 that being the case, as a consequence","「這下子」表示因為剛才發生的事，產生了新的結果，可以是好事，也可以是壞事。","「这下子」表示因为刚才发生的事，产生了新的结果，可以是好事，也可以是坏事。","這下子 = ahora sí, con esto. Señala la consecuencia de lo que acaba de ocurrir (buena o mala).","這下子 means 'now, with this': it points to the consequence of what just happened, good or bad."],"4-8-5":["Congeniar: V 得來／不來","Verb Complement 來 personable","Verb Complement 来 personable","「動詞＋得來／不來」表示跟某人或某件事合不合得上，例如「合得來」「談得來」「合不來」。","「动词＋得来／不来」表示跟某人或某件事合不合得上，例如「合得来」「谈得来」「合不来」。","Verbo + 得來 / 不來 expresa si algo se lleva bien con uno: 合得來 (llevarse bien), 談得來 (conectar al conversar), 合不來 (no congeniar).","Verb + 得來/不來 says whether you get along with someone or something suits you, as in 合得來, 談得來, 合不來."],"4-8-6":["Cuánto más: 何況","何況 let alone, no need to mention","何况 let alone, no need to mention","「何況」用更明顯的例子來加強前面的說法，意思是「更不用說」「而且」。","「何况」用更明显的例子来加强前面的说法，意思是「更不用说」「而且」。","何況 = y más aún, cuánto más. Para reforzar un argumento con un caso aún más claro.","何況 strengthens an argument with an even clearer case: 'let alone', 'not to mention'."],"4-8-7":["De lo contrario: 否則","否則 otherwise","否则 otherwise","「否則」表示如果前面說的事沒有做到，就會有不好的結果，意思是「不然」。","「否则」表示如果前面说的事没有做到，就会有不好的结果，意思是「不然」。","否則 = de lo contrario, si no. Introduce lo que pasará si no se cumple lo anterior.","否則 means 'otherwise': if the previous condition isn't met, something bad will happen."],"4-9-0":["Considerar: 把A當做B","把 A 當做 B to treat, take A as B","把 A 当做 B to treat, take A as B","「把 A 當做 B」表示把 A 看成 B，或用對待 B 的方式對待 A。","「把 A 当做 B」表示把 A 看成 B，或用对待 B 的方式对待 A。","把 A 當做 B = tratar o considerar a A como B.","把 A 當做 B means to treat or regard A as B."],"4-9-1":["Bajo, con: 在…下","在…下 under the…, due to the…","","「在……下」表示在某種條件、幫助或情況之下，例如「在……的幫助下」「在這種情況下」。","「在……下」表示在某种条件、帮助或情况之下，例如「在……的帮助下」「在这种情况下」。","在…下 = bajo, con (condición, ayuda o circunstancia): 在…的幫助下, 在這種情況下.","在…下 means 'under / with' a condition, help or circumstance, as in 在…的幫助下 and 在這種情況下."],"4-9-2":["Usos de 該","The Various Functions of 該","The Various Functions of 该","「該」可以表示「應該」（我該走了）、「到了該做某事的時候」（該……了），書面語裡也可以指前面提過的人或事，意思是「這個、那個」（該公司）。","「该」可以表示「应该」（我该走了）、「到了该做某事的时候」（该……了），书面语里也可以指前面提过的人或事，意思是「这个、那个」（该公司）。","該 tiene varios usos: «deber» (我該走了), «ya es hora de…» (該…了), y en lenguaje escrito «dicho, el mencionado» (該公司).","該 can mean 'should' (我該走了), 'it's time to…' (該…了), and in written language 'the said / that' (該公司)."],"4-9-3":["Desde que: 自從…以後","自從…以後 ever since...","自从…以后 ever since...","「自從……以後」表示從某個時間開始，到現在一直是同樣的情況。","「自从……以后」表示从某个时间开始，到现在一直是同样的情况。","自從 + tiempo + 以後 = desde que…; la situación empieza en ese momento y continúa hasta ahora.","自從…以後 means 'ever since': a situation starts at some point and has continued until now."],"4-9-4":["Usos de 幾","Summary of the Various Usages of 幾","Summary of the Various Usages of 几","「幾」可以問「多少」（你要幾個？）、表示不多的數量（幾天），放在數字後面表示零頭（十幾個），「好幾」表示相當多。","「几」可以问「多少」（你要几个？）、表示不多的数量（几天），放在数字后面表示零头（十几个），「好几」表示相当多。","幾 pregunta «cuántos» (números pequeños), significa «unos cuantos» (幾天) y, tras un número, «y tantos» (十幾個). 好幾 = bastantes.","幾 asks 'how many' (small numbers), means 'a few' (幾天), means 'and some' after a number (十幾個), and 好幾 means 'quite a lot'."],"4-9-5":["No poder evitar: 不禁","不禁 uncontrollably, cannot help but…","","「不禁」表示忍不住做某個動作，是自然、不自覺的反應。","「不禁」表示忍不住做某个动作，是自然、不自觉的反应。","不禁 + verbo = no poder evitar hacer algo (una reacción involuntaria).","不禁 means 'can't help (doing something)': an involuntary, natural reaction."],"4-9-6":["Todavía: 仍然","仍然 still the same, same as before","","「仍然」表示經過一段時間或有了變化，情況還是和以前一樣。","「仍然」表示经过一段时间或有了变化，情况还是和以前一样。","仍然 = todavía, aun así. La situación no cambia a pesar del tiempo o de las circunstancias.","仍然 means 'still / even so': the situation stays the same despite time or circumstances."],"4-9-7":["En realidad: 究竟","究竟 I wonder","","「究竟」用在疑問句裡，追問真正的答案，意思是「到底」，語氣比「到底」正式。","「究竟」用在疑问句里，追问真正的答案，意思是「到底」，语气比「到底」正式。","究竟 = en realidad, a fin de cuentas. Se usa en preguntas para insistir en la respuesta; es más formal que 到底.","究竟 is used in questions to press for the real answer: 'on earth, exactly'. It's more formal than 到底."],"4-10-0":["Usos de 著","Summary of the Various Functions of 著","Summary of the Various Functions of 着","「著」可以表示狀態持續（牆上掛著畫）、動作的方式（笑著說），也可以表示背景動作正在進行。","「着」可以表示状态持续（墙上挂着画）、动作的方式（笑着说），也可以表示背景动作正在进行。","著 marca un estado que continúa (牆上掛著畫), la manera en que se hace una acción (笑著說) y también una acción de fondo que sigue en curso.","著 can mark a continuing state (牆上掛著畫), the manner of an action (笑著說), or an ongoing background action."],"4-10-1":["Usos de 中","The Various Meanings of 中","","「中」（ㄓㄨㄥ）表示在某個範圍或過程裡，例如「討論中」；讀成ㄓㄨㄥˋ時是「打中、得到」的意思，例如「中獎」。","「中」（ㄓㄨㄥ）表示在某个范围或过程里，例如「讨论中」；读成ㄓㄨㄥˋ时是「打中、得到」的意思，例如「中奖」。","中 (zhōng) = en, durante, dentro de; indica algo en proceso (討論中). Leído zhòng significa «acertar, ganar» (中獎).","中 (zhōng) means 'in / during', showing something is in progress (討論中). Read zhòng, it means 'to hit / win' (中獎)."],"4-10-2":["Parece que: 似乎","似乎 it seems that, it gives somebody the impression that","","「似乎」表示根據看到或聽到的情況，覺得好像是這樣，語氣比「好像」稍微正式。","「似乎」表示根据看到或听到的情况，觉得好像是这样，语气比「好像」稍微正式。","似乎 = parece que. Expresa una impresión o suposición, con tono algo más formal que 好像.","似乎 means 'it seems that': an impression or guess based on what you see or hear, a bit more formal than 好像."],"4-10-3":["«Con» formal: 以","Classical Chinese Preposition 以","","「以」是書面語的介詞，意思是「用、憑」，常見於「以……為……」「以電話」「以免」等。","「以」是书面语的介词，意思是「用、凭」，常见于「以……为……」「以电话」「以免」等。","以 es una preposición de lengua escrita: «con, por medio de». Se ve en 以…為…, 以電話, 以免.","以 is a written-language preposition meaning 'with / by means of', seen in 以…為…, 以電話, 以免."],"4-10-4":["Tener madera: 是…的料","是…的料 to be gifted in…","","「是……的料」表示天生適合做某件事，常用否定形式「不是……的料」。","「是……的料」表示天生适合做某件事，常用否定形式「不是……的料」。","是…的料 = tener madera para, estar hecho para algo (un talento natural). Se usa más en la negación: 不是…的料.","是…的料 means 'cut out for…': a natural talent for something, most often used negatively as 不是…的料."],"4-10-5":["Usos de 下去","Summary of 下去","","動詞後面的「下去」可以表示往下走（走下去）、繼續做下去（做下去），否定時表示沒辦法再繼續（撐不下去）。","动词后面的「下去」可以表示往下走（走下去）、继续做下去（做下去），否定时表示没办法再继续（撑不下去）。","下去 después de un verbo puede significar: ir hacia abajo (走下去), seguir haciendo algo (做下去) y, en negativo, no poder continuar (撐不下去).","下去 after a verb can mean going down (走下去), continuing (做下去), or, in the negative, being unable to carry on (撐不下去)."],"4-10-6":["«Desde» formal: 自","自 from (formal)","","「自」是書面語，意思是「從」，常見於「自古以來」「自……起」。","「自」是书面语，意思是「从」，常见于「自古以来」「自……起」。","自 = desde (lengua escrita o formal): 自古以來, 自…起. Equivale a 從 en un registro más formal.","自 is a formal, written word meaning 'from / since', as in 自古以來 and 自…起."],"4-11-0":["Justo cuando: 偏偏","偏偏 contrary to expectation, against the speaker’s wish, annoyingly","","「偏偏」表示事情剛好跟希望的相反，或故意跟別人的意見相反，常有一點不高興或無奈的語氣。","「偏偏」表示事情刚好跟希望的相反，或故意跟别人的意见相反，常有一点不高兴或无奈的语气。","偏偏 = justo, precisamente (contra lo que se desea). Se usa para algo molesto o contrario a la voluntad de alguien.","偏偏 means 'of all things / just when': things turn out contrary to what's wanted, or someone stubbornly does the opposite, often with an annoyed tone."],"4-11-1":["Como siempre: 照","照 persist","","「照」加動詞（照樣、照常）表示不管情況有沒有改變，還是照以前的方式做。","「照」加动词（照样、照常）表示不管情况有没有改变，还是照以前的方式做。","照 + verbo (照樣, 照常) = hacer lo mismo que antes, a pesar del cambio o del obstáculo.","照 + verb (照樣, 照常) means to carry on as before regardless of changes or obstacles."],"4-11-2":["Raro: 難得","難得 rarely","难得 rarely","「難得」表示不常有、很少發生，所以特別可貴。也可以當形容詞，意思是「珍貴」。","「难得」表示不常有、很少发生，所以特别可贵。也可以当形容词，意思是「珍贵」。","難得 = raro, poco frecuente; algo que no ocurre a menudo y por eso se valora. También es adjetivo: «valioso».","難得 means 'rare / seldom': something that doesn't happen often and is therefore valued. It can also be an adjective meaning 'precious'."],"4-11-3":["En ratos libres: 在…之餘","在…之餘 while not otherwise engaged in …, apart from…","在…之余 while not otherwise engaged in …, apart from…","「在……之餘」表示除了主要的事以外，在剩下的時間裡還做了別的事。","「在……之余」表示除了主要的事以外，在剩下的时间里还做了别的事。","在…之餘 = además de / en los ratos libres de (una actividad principal), también se hace otra cosa.","在…之餘 means 'in the time left over from (a main activity)': besides the main thing, you also did something else."],"4-11-4":["Difícil de: 難以","難以 to find it difficult to…","难以 to find it difficult to…","「難以」加動詞表示很難做到，語氣正式，常搭配雙音節動詞，例如「難以相信」「難以想像」。","「难以」加动词表示很难做到，语气正式，常搭配双音节动词，例如「难以相信」「难以想像」。","難以 + verbo = difícil de…. Es formal y se usa con verbos de dos sílabas: 難以相信, 難以想像.","難以 + verb means 'difficult to…'. It is formal and usually pairs with two-syllable verbs, as in 難以相信 and 難以想像."],"4-11-5":["Poco a poco: 漸漸","漸漸 gradually, slowly","渐渐 gradually, slowly","「漸漸」表示變化慢慢地、一步一步地發生，意思是「慢慢地」。","「渐渐」表示变化慢慢地、一步一步地发生，意思是「慢慢地」。","漸漸 = poco a poco, gradualmente. Describe un cambio lento que va avanzando.","漸漸 means 'gradually': a change happens slowly, step by step."],"4-11-6":["Se ve que: 可見","可見 It can thus be concluded that…","可见 It can thus be concluded that…","「可見」表示從前面的事實可以得到一個結論，意思是「由此可知」。","「可见」表示从前面的事实可以得到一个结论，意思是「由此可知」。","可見 = se puede ver que, esto demuestra que. Saca una conclusión a partir de lo anterior.","可見 means 'it can be seen that': you draw a conclusion from the facts just mentioned."],"4-11-7":["Para X: 對於…而言","對於…而言 as far as… is concerned","对于…而言 as far as… is concerned","「對於 X 而言」表示從 X 的角度來看，是「對 X 來說」的比較正式說法。","「对于 X 而言」表示从 X 的角度来看，是「对 X 来说」的比较正式说法。","對於 X 而言 = para X, en lo que se refiere a X. Es la forma más formal de 對 X 來說.","對於 X 而言 means 'as far as X is concerned': a more formal version of 對 X 來說."],"4-12-0":["Da igual: 無所謂","無所謂 does not matter","无所谓 does not matter","「無所謂」表示怎麼樣都可以，不在意，沒有特別的意見。","「无所谓」表示怎么样都可以，不在意，没有特别的意见。","無所謂 = da igual, no importa. Se dice cuando a uno le es indiferente la opción.","無所謂 means 'it doesn't matter / I don't mind': you're indifferent to the choice."],"4-12-1":["¿Quién iba a decir?: 誰知道","誰知道 who would have thought…?","谁知道 who would have thought…?","「誰知道」表示出乎意料，常用在原本的計畫之後，意思是「沒想到」。也可以表示「不知道」。","「谁知道」表示出乎意料，常用在原本的计划之后，意思是「没想到」。也可以表示「不知道」。","誰知道 = ¿quién iba a pensar…? (algo inesperado después de lo planeado). También puede significar «quién sabe».","誰知道 means 'who would have thought': something unexpected happens after the plan. It can also mean 'who knows'."],"4-12-2":["De A hasta B: 小自…大至…","小自…大至… everything from A to Z","","「小自 A，大至 B」表示範圍很廣，從最小的 A 到最大的 B 都包括在內。","「小自 A，大至 B」表示范围很广，从最小的 A 到最大的 B 都包括在内。","小自 A，大至 B = desde A (lo más pequeño) hasta B (lo más grande): abarca todo el rango.","小自 A, 大至 B means 'from the smallest A to the biggest B': it covers the whole range."],"4-12-3":["¡Increíble!: 竟然","竟然 to the speaker’s great surprise","","「竟然」表示說話的人覺得很意外，沒想到事情會這樣。","「竟然」表示说话的人觉得很意外，没想到事情会这样。","竟然 = ¡increíblemente!, ¡quién lo diría! Expresa gran sorpresa del hablante ante algo inesperado.","竟然 expresses the speaker's great surprise that something turned out unexpectedly."],"4-12-4":["En teoría: 照理說","照理說 normally","照理说 normally","「照理說」表示依照一般的道理，事情應該是這樣，後面常常接著說實際上不是這樣。","「照理说」表示依照一般的道理，事情应该是这样，后面常常接着说实际上不是这样。","照理說 = en teoría, normalmente. Plantea lo que debería ser lo normal, y suele seguir un contraste.","照理說 means 'normally / in theory': it states what should be the case, and is often followed by a contrast."],"4-12-5":["Tomar A como B: 以A為B","以A為B to take A as B","以A为B to take A as B","「以 A 為 B」表示把 A 當作 B，例如當作榜樣、重點或基礎，語氣正式。","「以 A 为 B」表示把 A 当作 B，例如当作榜样、重点或基础，语气正式。","以 A 為 B = tomar A como B (como modelo, prioridad o base). Es formal.","以 A 為 B means 'take A as B': as a model, priority or basis. It is formal."],"4-12-6":["No importa…: 無論…都…","無論…都… regardless of what…","无论…都… regardless of what…","「無論……都……」表示不管是哪一種情況，結果都一樣。「無論」後面通常有疑問詞或選擇。","「无论……都……」表示不管是哪一种情况，结果都一样。「无论」后面通常有疑问词或选择。","無論…都… = no importa qué / cómo…, siempre…. Introduce una condición con varias opciones y el mismo resultado.","無論…都… means 'no matter what/how…, always…': the result is the same in every case. 無論 is usually followed by a question word or choices."],"4-12-7":["Claramente: 明明","明明 It should be obvious to everyone that…","","「明明」表示事實很清楚，可是說的話或做的事卻和事實不一樣，常有責怪或不滿的語氣。","「明明」表示事实很清楚，可是说的话或做的事却和事实不一样，常有责怪或不满的语气。","明明 = claramente, a todas luces. Se usa cuando algo es obvio pero lo que se dice o hace lo contradice.","明明 means 'obviously': the facts are clear, yet what is said or done contradicts them, often with a tone of blame or dissatisfaction."],"4-12-8":["Hacer que: 使得","Causation with 使得","","「使得」表示某件事造成了某個結果，主語常常不是人。","「使得」表示某件事造成了某个结果，主语常常不是人。","使得 = hacer que, provocar. Expresa que un hecho causa un resultado (suele ser un sujeto no humano).","使得 means 'to cause / make': one event causes a result, and the subject is often not a person."],"5-1-0":["Incluso B no es la excepción","Even B is no exception","","先說 A 的一般情況，再強調連最特別、最容易被排除的 B 也一樣，沒有例外。多用在書面或正式的說明。","先说 A 的一般情况，再强调连最特别、最容易被排除的 B 也一样，没有例外。多用在书面或正式的说明。","即使是 B 也不例外 = ni siquiera B es una excepción. Primero se afirma algo de A en general y luego se subraya que incluso el caso que se esperaría exento (B) cumple la misma regla. Registro algo formal.","First state what holds for A in general, then stress that even B, the case you might expect to be exempt, is no different. More formal or written in tone."],"5-1-1":["Una vez que A, entonces B","Once A happens, B follows","","「一旦」表示「一 A 發生，B 就會（可能）跟著發生」，A 通常是不容易發生、但一發生就會有大影響的情況。B 常搭配「就」，是書面、正式的說法。","「一旦」表示「一 A 发生，B 就会（可能）跟着发生」，A 通常是不容易发生、但一发生就会有大影响的情况。B 常搭配「就」，是书面、正式的说法。","一旦 = una vez que / en cuanto. A es una condición que, si llega a ocurrir, trae consigo una consecuencia importante B. B suele llevar 就 (más raro con 才). Registro escrito o formal; A suele ser algo que se quiere evitar o una decisión seria.","一旦 means 'once' or 'the moment that'. A is a condition that, if it ever happens, brings a significant result B. B usually takes 就 (less commonly 才). Written or formal register."],"5-1-2":["Hacer A solo por hacer A","Doing A just for the sake of A","","把同一個動詞放在「為」和「而」前後，表示只是為了做這件事而做，沒有真正的理由或目的。常帶批評的語氣。","把同一个动词放在「为」和「而」前后，表示只是为了做这件事而做，没有真正的理由或目的。常带批评的语气。","為 A 而 A repite el mismo verbo (o palabra): hacer algo solo por hacerlo, sin una razón o un objetivo real (oponerse por oponerse, discutir por discutir). Suele llevar tono crítico.","The same verb appears on both sides: doing something purely for the sake of doing it, with no real reason or goal. It usually carries a critical tone."],"5-1-3":["En realidad / de hecho","In fact","","引出與前面說法不同、或更接近真實情況的事，常放在「但」「可是」後面或句首，後面常有逗號。口語也能用，書面更常見。","引出与前面说法不同、或更接近真实情况的事，常放在「但」「可是」后面或句首，后面常有逗号。口语也能用，书面更常见。","事實上 = en realidad, de hecho. Introduce lo que de verdad ocurre, a menudo corrigiendo o contradiciendo lo dicho antes. Suele ir al inicio de la oración, con frecuencia tras 但 o 可是, y seguido de coma.","事實上 means 'in fact' or 'actually'. It introduces what is really the case, often correcting or contradicting what was just said. It usually opens a clause, often after 但/可是, followed by a comma."],"5-1-4":["A se hace responsable de B","A is responsible for B","","「為 B 負責」表示對 B 這件事承擔責任，B 通常是自己做的事、說的話或決定。也可以說「對 B 負責」，意思很接近。","「为 B 负责」表示对 B 这件事承担责任，B 通常是自己做的事、说的话或决定。也可以说「对 B 负责」，意思很接近。","為 B 負責 = responsabilizarse de B, asumir la responsabilidad por B. B suele ser algo que A hizo, dijo o decidió. También se dice 對 B 負責 con un sentido muy parecido.","為 B 負責 means to take responsibility for B; B is usually something A did, said or decided. 對 B 負責 is also possible with a very similar meaning."],"5-1-5":["Taparle la boca a ...","To shut someone up / silence","","字面是「把嘴封起來」，比喻用壓力、金錢或手段不讓某人（或媒體）說話、批評或報導，帶有負面意思。","字面是「把嘴封起来」，比喻用压力、金钱或手段不让某人（或媒体）说话、批评或报导，带有负面意思。","封住…的嘴 = taparle la boca a alguien (lit. sellar su boca). Figurado: impedir que alguien hable, critique o informe, mediante presión, dinero u otros medios. Connotación negativa.","Literally 'seal someone's mouth'. Figuratively it means preventing a person or the media from speaking, criticizing or reporting, by pressure, money or other means. It has a negative tone."],"5-1-6":["A se esconde bajo el paraguas de B","A hides under B's protective umbrella","","「保護傘」比喻保護、庇護。這個句型表示 A 利用 B 當作擋箭牌或藉口，來避免責任或批評，通常帶批評的意思。","「保护伞」比喻保护、庇护。这个句型表示 A 利用 B 当作挡箭牌或借口，来避免责任或批评，通常带批评的意思。","保護傘 (paraguas protector) es una metáfora de amparo. A 躲在 B 的保護傘下 = A se esconde bajo el amparo de B, usándolo como excusa o escudo para evitar responsabilidad o críticas. Suele ser crítico.","保護傘 ('protective umbrella') is a metaphor for cover or shelter. The pattern means A hides behind B, using it as a shield or excuse to avoid responsibility or criticism; it is usually critical."],"5-1-7":["Esto es especialmente cierto","This is especially true","","先說一個一般的情況，再用「尤其如此」補充：在某個特定對象或情況下，更是這樣。常說「對…來說尤其如此」。","先说一个一般的情况，再用「尤其如此」补充：在某个特定对象或情况下，更是这样。常说「对…来说尤其如此」。","尤其如此 = esto es especialmente cierto. Tras una afirmación general se añade que en un caso concreto se cumple todavía más; suele decirse 對…來說尤其如此 o simplemente …尤其如此.","尤其如此 means 'this is especially so'. After a general statement it adds that in one particular case it holds even more; commonly 對…來說尤其如此."],"5-1-8":["En cambio / por su parte","On the other hand, whereas","","用來對比兩個部分：「有些…有些…則…」「…則…」。「則」放在第二部分的主語後面、動詞前面，是書面語。","用来对比两个部分：「有些…有些…则…」「…则…」。「则」放在第二部分的主语后面、动词前面，是书面语。","則 marca contraste entre dos partes: 有些…有些…則… (unos…, otros en cambio…). Va después del sujeto de la segunda parte y antes del verbo. Registro escrito.","則 contrasts two parts: 有些…有些…則… ('some…, others…'). It goes after the subject of the second part and before the verb. Written register."],"5-1-9":["A en nombre de B","A in the name of B","","「以 B 之名」表示打著 B（常是好聽的理由，如愛、正義、安全）的名義做 A。常暗示這個理由只是藉口，是書面用法。","「以 B 之名」表示打着 B（常是好听的理由，如爱、正义、安全）的名义做 A。常暗示这个理由只是借口，是书面用法。","以 B 之名 = en nombre de B, bajo el pretexto de B. B suele ser una causa noble (amor, justicia, seguridad) y a menudo se sugiere que es solo una excusa. Registro escrito.","以 B 之名 means 'in the name of B' (often something noble like love, justice or safety), often hinting that it is only a pretext. Written register."],"5-1-10":["Ni hablar de B","Not to mention B","","先說 A 已經是這樣（常是比較容易的例子），再說 B 的程度更高，所以更是這樣，不用多說。B 通常是更極端的情況。","先说 A 已经是这样（常是比较容易的例子），再说 B 的程度更高，所以更是这样，不用多说。B 通常是更极端的情况。","B 就更不用說了 = de B ni se diga. Primero se presenta A, que ya cumple lo dicho, y luego se señala que B (un caso más extremo) lo cumple con mayor razón. Sirve de remate.","B 就更不用說了 means 'B goes without saying'. After presenting A, which already fits, it adds that B, a more extreme case, fits all the more."],"5-1-11":["Al mismo tiempo que A, también B","While A, also B","","表示做 A 的時候，也要同時做或注意 B。B 常是提醒、補充或相對的另一面。「在」可以省略，常用在書面或演講。","表示做 A 的时候，也要同时做或注意 B。B 常是提醒、补充或相对的另一面。「在」可以省略，常用在书面或演讲。","(在) A 的同時，也 B = al mismo tiempo que A, también B. Se usa para recordar que, mientras se hace A, hay que hacer o cuidar también B (algo complementario o una advertencia). 在 es opcional.","(在) A 的同時，也 B means 'while A, also B': while doing A you should also do or watch out for B, often a reminder or complementary point. 在 is optional."],"5-2-0":["Ya que A, ¿por qué todavía B?","Since A, why still B?","","先承認一個已知的事實 A，再用反問表示 B 和 A 互相矛盾、不合理。是帶有質疑或責備語氣的問句。","先承认一个已知的事实 A，再用反问表示 B 和 A 互相矛盾、不合理。是带有质疑或责备语气的问句。","既然 A，為什麼還 B 呢？ = ya que A, ¿por qué todavía B? A es un hecho ya aceptado y la pregunta retórica señala que B contradice a A. Tono de cuestionamiento o reproche.","既然 A，為什麼還 B 呢？ means 'since A, why still B?'. A is an accepted fact, and the rhetorical question shows that B contradicts it. It carries a tone of challenge or reproach."],"5-2-1":["Tarde o temprano","Sooner or later","","「早晚」表示遲早、總有一天會發生。可以當副詞（早晚會…），也可以說「是早晚的事」，意思是只是時間問題。","「早晚」表示迟早、总有一天会发生。可以当副词（早晚会…），也可以说「是早晚的事」，意思是只是时间问题。","早晚 = tarde o temprano. Puede funcionar como adverbio (早晚會…) o en la forma 是早晚的事, 'es cuestión de tiempo'.","早晚 means 'sooner or later'. It can be an adverb (早晚會…) or appear as 是早晚的事, 'it is only a matter of time'."],"5-2-2":["No solo A, sino sobre todo B","Not only A, but more importantly B","","先列出 A（可以有好幾項），再用「更重要的是」帶出最重要的一項 B。書面或正式說明常用，A 和 B 通常是同一類的事。","先列出 A（可以有好几项），再用「更重要的是」带出最重要的一项 B。书面或正式说明常用，A 和 B 通常是同一类的事。","不僅 A，更重要的是 B = no solo A, sino sobre todo (lo más importante es) B. Se enumera A (puede haber varios elementos) y se destaca B como lo más importante. Registro escrito o formal.","不僅 A，更重要的是 B means 'not only A, but more importantly B'. A may list several items and B is highlighted as the most important. Written or formal register."],"5-2-3":["Se supone que deberías… (¡debería…!)","Should… (so it ought to be)","","「應該…才對」說明按道理或規定，正確的做法是這樣；常用來提醒別人、糾正，或表示對現況不滿。句尾「才對」不能省略。","「应该…才对」说明按道理或规定，正确的做法是这样；常用来提醒别人、纠正，或表示对现况不满。句尾「才对」不能省略。","應該…才對 = debería… / lo correcto es… Indica lo que es razonable o debido, y se usa para recordar, corregir o expresar queja por lo que ocurre. 才對 al final es indispensable.","應該…才對 means 'should… (that would be the right thing)'. It states what is proper or reasonable, and is used to remind, correct or express dissatisfaction. 才對 at the end is essential."],"5-2-4":["No hay ... alguno / carecer de ...","Utterly lacking …","","「毫無」是完全沒有，「可言」表示值得說的；合起來是「完全沒有…可說」，語氣很強。…處常放「效果、意義、價值、自由、隱私」等抽象名詞，是書面語。","「毫无」是完全没有，「可言」表示值得说的；合起来是「完全没有…可说」，语气很强。…处常放「效果、意义、价值、自由、隐私」等抽象名词，是书面语。","毫無…可言 = no hay absolutamente nada de … que mencionar; carecer por completo de …. Tono muy fuerte y registro escrito. Se usa con sustantivos abstractos: 效果, 意義, 價值, 自由, 隱私.","毫無…可言 means 'there is absolutely no … to speak of'. It is strong and written, used with abstract nouns such as 效果, 意義, 價值, 自由 and 隱私."],"5-2-5":["En realidad es A y no B","It's actually A, not B","","用來糾正一般人的想法或常見的誤會：大家以為是 B，但真正是 A。「而不是」後面的 B 就是被否定的說法。","用来纠正一般人的想法或常见的误会：大家以为是 B，但真正是 A。「而不是」后面的 B 就是被否定的说法。","其實是 A 而不是 B = en realidad es A y no B. Corrige una idea o malentendido común: se piensa que es B, pero lo cierto es A. Lo que va tras 而不是 es lo que se descarta.","其實是 A 而不是 B means 'it's actually A, not B'. It corrects a common assumption: people think B, but the truth is A. What follows 而不是 is the rejected view."],"5-2-6":["¿Cómo se puede…?","How could one…?","","反問句，表示「不應該／不可以」，語氣帶有不贊成或不滿。不是真的問方法。「呢」可以加強質問的語氣。","反问句，表示「不应该／不可以」，语气带有不赞成或不满。不是真的问方法。「呢」可以加强质问的语气。","怎麼能…呢？ = ¿cómo se puede…? / ¿cómo es posible que…? Pregunta retórica que expresa que algo no debería hacerse o no es aceptable; indica desaprobación. No pide información sobre un método.","怎麼能…呢？ means 'how could… ?' It is a rhetorical question meaning something should not be done or is unacceptable, showing disapproval rather than asking how."],"5-2-7":["Desde el punto de vista de… / a juzgar por…","Judging from…, from the standpoint of…","","「從」後面放事實、資料或觀點，表示根據這個來判斷或分析，後面接結論。比「根據」更常用在說明角度。","「从」后面放事实、资料或观点，表示根据这个来判断或分析，后面接结论。比「根据」更常用在说明角度。","從…來看 = a juzgar por…, desde el punto de vista de…. Tras 從 se coloca un dato, un hecho o una perspectiva en que se basa la conclusión que sigue.","從…來看 means 'judging from…' or 'from the perspective of…'. After 從 come the facts, data or viewpoint on which the following conclusion is based."],"5-2-8":["…, para (con el fin de)…","…, in order to…","","放在句子後半，「以」後面接動詞（片語），表示前面做某件事的目的，意思像「為了」。是書面語，口語較少用。","放在句子后半，「以」后面接动词（片语），表示前面做某件事的目的，意思像「为了」。是书面语，口语较少用。","以 + verbo, colocado en la segunda parte de la oración, indica la finalidad de lo anterior (como 為了, 'con el fin de'). Registro escrito; poco habitual en la lengua hablada.","以 followed by a verb phrase, placed in the second half of the sentence, states the purpose of what came before, like 為了 ('in order to'). Written register, rarely used in speech."],"5-3-0":["Tener tendencia a…","There is a trend toward…","","「趨勢」是發展的方向。「有…的趨勢」常接增加、減少、上升等動詞，說明事情正朝某個方向發展。書面、新聞常用。","「趋势」是发展的方向。「有…的趋势」常接增加、减少、上升等动词，说明事情正朝某个方向发展。书面、新闻常用。","有…的趨勢 = hay una tendencia a… 趨勢 es la dirección en que algo evoluciona; suele combinarse con verbos como 增加, 減少, 上升, 普及. Común en textos escritos y noticias.","有…的趨勢 means 'there is a trend toward…'. 趨勢 is the direction something is developing; it often combines with verbs like 增加, 減少, 上升 or 普及. Common in news and writing."],"5-3-1":["Sin importar el costo","Regardless of cost, at all costs","","「不計」是不考慮，「一切」是所有；合起來是不管任何代價、後果，一心去做。常見搭配有「不計一切代價」，是書面語。","「不计」是不考虑，「一切」是所有；合起来是不管任何代价、后果，一心去做。常见搭配有「不计一切代价」，是书面语。","不計一切 = sin tener en cuenta nada, a cualquier costo. 不計 es 'no contar', 一切 'todo'. Frecuente en la expresión fija 不計一切代價. Registro escrito.","不計一切 means 'disregarding everything', i.e. at any cost. 不計 is 'not count' and 一切 'everything'; the set phrase 不計一切代價 is common. Written register."],"5-3-2":["Ganarse el favor de…","To win the favor of…","","「青睞」是特別的喜愛、重視。「獲得…青睞」表示受到某人或某群人的歡迎、看重，是書面語。也可以反過來否定：「沒有獲得…的青睞」。","「青睐」是特别的喜爱、重视。「获得…青睐」表示受到某人或某群人的欢迎、看重，是书面语。也可以反过来否定：「没有获得…的青睐」。","獲得…(的)青睞 = ganarse el favor (la preferencia) de…. 青睞 es una especial predilección. Se usa en escritos y puede negarse: 沒有獲得…的青睞 (no convencer a…).","獲得…(的)青睞 means 'to win someone's favor'. 青睞 is special liking or preference. Written register; it can be negated as 沒有獲得…的青睞."],"5-3-3":["Invertir A en B","To invest A in B","","A 是金錢、時間、精力等資源，B 是要投入的對象。用「把」字句，表示把資源放在 B 上。也可以說「在 B 上投資 A」。","A 是金钱、时间、精力等资源，B 是要投入的对象。用「把」字句，表示把资源放在 B 上。也可以说「在 B 上投资 A」。","把 A 投資在 B 上 = invertir A en B. A es un recurso (dinero, tiempo, energía) y B es en lo que se invierte. Estructura con 把.","把 A 投資在 B 上 means 'to invest A in B'. A is a resource (money, time, energy) and B is where it goes. It is a 把 sentence."],"5-3-4":["Padecer mucho de…","To suffer greatly from…","","「飽受」是受了很多、很久；「之苦」是…的痛苦。常接戰爭、疾病、貧窮、天災等不好的事，是書面語。","「饱受」是受了很多、很久；「之苦」是…的痛苦。常接战争、疾病、贫穷、天灾等不好的事，是书面语。","飽受…之苦 = sufrir mucho de…, padecer…. 飽受 indica sufrir mucho o por mucho tiempo; se combina con sustantivos negativos (戰爭, 疾病, 貧窮, 天災). Registro escrito.","飽受…之苦 means 'to suffer a great deal from…'. 飽受 implies suffering heavily or for a long time; it goes with negative nouns like 戰爭, 疾病, 貧窮, 天災. Written register."],"5-3-5":["Antes A, ahora B","Originally A, now B","","「原來」是本來、起初；「如今」是現在，書面語。用來對比以前和現在的變化。注意這裡的「原來」不是「原來如此」的恍然大悟。","「原来」是本来、起初；「如今」是现在，书面语。用来对比以前和现在的变化。注意这里的「原来」不是「原来如此」的恍然大悟。","原來 A，如今 B = antes A, ahora B. 原來 es 'originalmente'; 如今 es 'hoy en día' (escrito). Contrasta un pasado con el presente. Ojo: aquí 原來 no significa '¡ah, así que era eso!'.","原來 A，如今 B means 'originally A, but now B'. 原來 is 'originally'; 如今 is 'nowadays' (written). It contrasts past and present. Note: 原來 here is not the 'oh, I see!' sense."],"5-3-6":["De A, y de ahí, B","From A, and then on to B","","「進而」表示在 A 的基礎上更進一步，發展成 B。A 到 B 是一個逐步進展的過程。書面語。","「进而」表示在 A 的基础上更进一步，发展成 B。A 到 B 是一个逐步进展的过程。书面语。","從 A，進而 B = de A, y a partir de ahí, B. 進而 indica que, sobre la base de A, se avanza un paso más hasta B; es un proceso gradual. Registro escrito.","從 A，進而 B means 'from A, and going a step further, B'. 進而 shows progress from A to B in a gradual process. Written register."],"5-3-7":["Si A, ¿cómo es que B?","If A, how could B?","","「若」是「如果」，比較書面。這個句型用反問表示：如果 A 是真的，B 就不合理，所以 B 不應該發生。","「若」是「如果」，比较书面。这个句型用反问表示：如果 A 是真的，B 就不合理，所以 B 不应该发生。","若 A，怎麼會 B？ = si A, ¿cómo es que B? 若 equivale a 如果 pero más escrito. La pregunta retórica señala que, siendo cierto A, B no tendría sentido.","若 A，怎麼會 B？ means 'if A, how could B?'. 若 is a more formal 如果. The rhetorical question shows that if A were true, B would not make sense."],"5-3-8":["Incluir A en B","To include A in B","","「列入」是放進名單、計畫或類別裡。「把 A 列入 B」表示把 A 放進 B 中，B 通常是名單、計畫、議程或項目。","「列入」是放进名单、计划或类别里。「把 A 列入 B」表示把 A 放进 B 中，B 通常是名单、计划、议程或项目。","把 A 列入 B = incluir A en B (en una lista, un plan, una agenda o una categoría). 列入 significa 'poner dentro de la lista'. Estructura con 把.","把 A 列入 B means 'to put A on B', where B is a list, plan, agenda or category. 列入 is 'to list/include'. It is a 把 sentence."],"5-3-9":["Ponerle a A la etiqueta de B","To label A as B","","「貼標籤」比喻用一個簡單的印象或名稱來定義一個人或一群人，常帶有刻板印象的意思。B 是被貼上的標籤。","「贴标签」比喻用一个简单的印象或名称来定义一个人或一群人，常带有刻板印象的意思。B 是被贴上的标签。","給 A 貼上 B 的標籤 = ponerle a A la etiqueta de B. Figurado: definir a una persona o grupo con una impresión simple, a menudo un estereotipo. B es la etiqueta.","給 A 貼上 B 的標籤 means 'to stick the label B on A', figuratively defining a person or group with a simple impression, often a stereotype."],"5-3-10":["Sin duda es…","Undoubtedly it is…","","「無疑」是沒有疑問，「無疑是…」表示說話者很肯定地判斷。常用在書面評論或說明，語氣比「一定是」更正式。","「无疑」是没有疑问，「无疑是…」表示说话者很肯定地判断。常用在书面评论或说明，语气比「一定是」更正式。","無疑是… = sin duda es…. 無疑 significa 'sin lugar a dudas'. El hablante hace un juicio muy seguro; es más formal que 一定是 y típico de comentarios escritos.","無疑是… means 'it is without doubt…'. 無疑 is 'no doubt', expressing a firm judgment; more formal than 一定是 and typical of written commentary."],"5-4-0":["Desde… hasta hoy","From… until now","","「自」表示從（書面語），「至今」是到現在。用來說明某件事從過去某個時間開始一直到現在。「自」後面放時間點或事件。","「自」表示从（书面语），「至今」是到现在。用来说明某件事从过去某个时间开始一直到现在。「自」后面放时间点或事件。","自…至今 = desde… hasta hoy. 自 equivale a 從 (escrito) y 至今 a 'hasta ahora'. Indica que algo continúa desde un momento del pasado hasta el presente; tras 自 va un momento o un hecho.","自…至今 means 'from… until now'. 自 is a written 從 and 至今 is 'up to the present'. After 自 comes a point in time or an event."],"5-4-1":["Hacer A mientras se hace B","Doing A while doing B","","表示同一個人同時做兩件事。常寫成「一面…一面…」，和「一邊…一邊…」相近，「一面」比較書面。兩個動作通常都是持續的。","表示同一个人同时做两件事。常写成「一面…一面…」，和「一边…一边…」相近，「一面」比较书面。两个动作通常都是持续的。","一面 A 一面 B = hacer A mientras (al mismo tiempo) se hace B. Una misma persona realiza dos acciones simultáneas. Similar a 一邊…一邊…, pero 一面 es algo más escrito. Los dos verbos suelen ser acciones continuas.","一面 A 一面 B means doing A and B at the same time by the same person. Similar to 一邊…一邊…, but 一面 is somewhat more written. Both verbs are typically continuing actions."],"5-4-2":["Ser necesario…","There is a need to…","","「必要」是需要。「有…的必要」表示有做某件事的需要或理由；否定用「沒有…的必要」，表示不需要。","「必要」是需要。「有…的必要」表示有做某件事的需要或理由；否定用「没有…的必要」，表示不需要。","有…的必要 = es necesario…, hay necesidad de…. Su negación 沒有…的必要 significa 'no hace falta…'. Registro algo formal.","有…的必要 means 'there is a need to…'. Its negative 沒有…的必要 means 'there is no need to…'. Somewhat formal."],"5-4-3":["No solo no A, sino que más bien B","Not only not A, but rather B","","預期是 A，結果卻不是，而且出現相反的 B。「反而」表示結果與預期相反。A 常是「好轉、改善」等期待的結果，B 是更差的情況。","预期是 A，结果却不是，而且出现相反的 B。「反而」表示结果与预期相反。A 常是「好转、改善」等期待的结果，B 是更差的情况。","不但不（沒）A 反而 B = no solo no A, sino que (al contrario) B. Se esperaba A, pero no solo no ocurrió sino que pasó lo opuesto. 反而 marca el resultado contrario a lo esperado.","不但不（沒）A 反而 B means 'not only did A not happen, but on the contrary B'. A was expected but didn't happen and the opposite B did. 反而 marks the unexpected opposite result."],"5-4-4":["Clasificar A como B","To list A as B","","「將」是「把」的書面語。「列為」是正式列入、指定成為某種類別或等級。多用在政府公告、新聞，B 是新的身分或類別。","「将」是「把」的书面语。「列为」是正式列入、指定成为某种类别或等级。多用在政府公告、新闻，B 是新的身分或类别。","將 A 列為 B = clasificar (declarar, designar) A como B. 將 es la forma escrita de 把. 列為 indica incluir formalmente en una categoría o nivel. Típico de comunicados y noticias.","將 A 列為 B means 'to designate A as B'. 將 is the written version of 把; 列為 is to formally place something in a category or rank. Typical of official announcements and news."],"5-4-5":["Perjudicial / favorable para…","Detrimental / beneficial to…","","「有利於 A」是對 A 有好處，「不利於 A」是對 A 不好。「於」可以省略。A 常是名詞或動作，如健康、發展、學習。書面、正式說明常用。","「有利于 A」是对 A 有好处，「不利于 A」是对 A 不好。「于」可以省略。A 常是名词或动作，如健康、发展、学习。书面、正式说明常用。","有利(於)A = favorable para A, beneficioso para A; 不利(於)A = perjudicial para A. 於 puede omitirse. A suele ser un sustantivo o acción (健康, 發展, 學習). Frecuente en textos formales.","有利(於)A means 'beneficial to A' and 不利(於)A 'detrimental to A'. 於 is optional. A is often a noun or an action such as 健康, 發展 or 學習. Common in formal writing."],"5-4-6":["En el proceso de…","In the course of…","","「過程」是從開始到結束的經過。「在…過程中」表示在做某件事的期間，後面說這期間發生的事或做的事。","「过程」是从开始到结束的经过。「在…过程中」表示在做某件事的期间，后面说这期间发生的事或做的事。","在…過程中 = en el proceso de…, durante…. 過程 es el desarrollo de algo de principio a fin; la oración dice lo que ocurre o se hace durante ese proceso.","在…過程中 means 'in the course of…'. 過程 is the process from start to finish; the sentence states what happens or is done during it."],"5-4-7":["Ya es hora de…","It's time to…","","表示現在正是該做某件事的時機，常說「現在該是…的時候了」。否定時說「不是…的時候」，表示還不是時候或不適合現在做。","表示现在正是该做某件事的时机，常说「现在该是…的时候了」。否定时说「不是…的时候」，表示还不是时候或不适合现在做。","是…的時候了 = ya es hora de…. Suele decirse 現在該是…的時候了. La negación 不是…的時候 (還不是…的時候) indica que todavía no es el momento o que no conviene hacerlo ahora.","是…的時候了 means 'it's time to…', often 現在該是…的時候了. The negative 不是…的時候 means it's not yet the time or not appropriate now."],"5-4-8":["A supera con mucho a B","A far exceeds B","","「遠遠」表示差距很大，「超過」是高於、多於。這個句型說明 A 比 B 高出很多，B 常是標準、預期或能力。","「远远」表示差距很大，「超过」是高于、多于。这个句型说明 A 比 B 高出很多，B 常是标准、预期或能力。","A 遠遠超過 B = A supera con mucho a B. 遠遠 indica una gran diferencia y 超過 'sobrepasar'. B suele ser un estándar, una expectativa o una capacidad.","A 遠遠超過 B means 'A far exceeds B'. 遠遠 stresses a big gap and 超過 is 'exceed'. B is often a standard, expectation or ability."],"5-5-0":["No tener más remedio / verse obligado a…","To have no choice but to…","","「不得已」是沒有辦法、不是自己願意的。可以說「是不得已的事」，也可以放在動詞前，常搭配「只好」：不得已只好…。","「不得已」是没有办法、不是自己愿意的。可以说「是不得已的事」，也可以放在动词前，常搭配「只好」：不得已只好…。","不得已 = no tener más remedio, verse obligado. Se puede usar como adjetivo (是不得已的事) o delante del verbo, con 只好: 不得已只好… = no queda más remedio que….","不得已 means 'having no choice', not by one's own wish. It can be used as 是不得已的事 or before a verb, often with 只好: 不得已只好… 'had no choice but to…'."],"5-5-1":["En cambio / mirando el otro lado","By contrast, looking at the other side","","先說一個情況，再用「反觀」帶出相對、相反的情況，用來比較。是書面語，常用在評論或報導，後面常有逗號。","先说一个情况，再用「反观」带出相对、相反的情况，用来比较。是书面语，常用在评论或报导，后面常有逗号。","反觀 = en cambio, por el contrario (si miramos el otro lado). Tras describir una situación, introduce otra que se le opone, para comparar. Registro escrito, típico de comentarios y reportajes.","反觀 means 'by contrast' or 'looking at the other side'. After describing one situation it introduces the opposite one for comparison. Written register, typical of commentary and reports."],"5-5-2":["Siempre / desde el principio hasta ahora","All along, throughout","","「始終」表示從開始到現在（或到最後）一直沒有變。常搭配否定「始終沒有／始終不…」，意思像「一直」，但更書面、更強調沒有改變。","「始终」表示从开始到现在（或到最后）一直没有变。常搭配否定「始终没有／始终不…」，意思像「一直」，但更书面、更强调没有改变。","始終 = siempre, desde el principio hasta ahora (o hasta el final) sin cambiar. Suele usarse con negación: 始終沒有／始終不…. Como 一直, pero más escrito y con más énfasis en que nada cambió.","始終 means 'all along', from beginning to now (or to the end) without change. Often with negation (始終沒有/始終不…). Like 一直 but more written and stressing no change."],"5-5-3":["Tanto A como B","Both A and B","","表示同時具備兩個特點或兩件事，常連接兩個形容詞或動詞，書面感較強。也可說「既…又…」。A、B 通常是同一方向的好處或壞處。","表示同时具备两个特点或两件事，常连接两个形容词或动词，书面感较强。也可说「既…又…」。A、B 通常是同一方向的好处或坏处。","既 A，也 B = tanto A como B; a la vez A y B. Une dos cualidades o hechos que coexisten, normalmente adjetivos o verbos; suena algo escrito. También existe 既…又…. A y B suelen apuntar en la misma dirección (ambos buenos o ambos malos).","既 A，也 B means 'both A and B', joining two qualities or facts that coexist, usually adjectives or verbs, with a somewhat written feel. 既…又… is similar. A and B usually point the same way (both good or both bad)."],"5-5-4":["Es verdad que A, pero B","Granted A, but B","","「固然」先承認 A 是對的、是事實，再用「但」「但是」「也」引出 B，真正想強調的是 B。像是「雖然 A，但是 B」，更書面。","「固然」先承认 A 是对的、是事实，再用「但」「但是」「也」引出 B，真正想强调的是 B。像是「虽然 A，但是 B」，更书面。","…固然 A 但 B = es cierto que A, pero B. 固然 concede primero que A es verdad o un hecho, y luego introduce con 但 / 但是 / 也 la idea que se quiere subrayar, B. Como 雖然…但是…, pero más escrito.","…固然 A 但 B means 'it is true that A, but B'. 固然 first concedes that A is correct or a fact, then 但/但是/也 introduces B, the real point. Like 雖然…但是… but more written."],"5-5-5":["En cuanto a… / por lo que respecta a…","As far as … is concerned","","「就」後面放一個範圍或角度，表示只從這個角度來說、評價。常用「就 A 而言」，後面接判斷或結論。書面、正式說明常見。","「就」后面放一个范围或角度，表示只从这个角度来说、评价。常用「就 A 而言」，后面接判断或结论。书面、正式说明常见。","就…而言 = en cuanto a…, por lo que respecta a…. Tras 就 va el ámbito o el punto de vista desde el que se hace la valoración; luego sigue un juicio o conclusión. Frecuente en textos formales.","就…而言 means 'as far as… is concerned'. After 就 comes the scope or angle from which the judgment is made, followed by a conclusion. Common in formal writing."],"5-5-6":["Definitivamente no es algo que…","Is definitely not something that…","","用「是…的」句型加強語氣，「絕對」表示完全否定。常用來糾正想法，說明某事物不是靠某種方法或條件就能得到，例如「…絕對不是…能夠…的」。","用「是…的」句型加强语气，「绝对」表示完全否定。常用来纠正想法，说明某事物不是靠某种方法或条件就能得到，例如「…绝对不是…能够…的」。","絕對不是…的 = definitivamente no es algo que…. Combina la estructura 是…的 con 絕對 para negar con mucha fuerza; sirve para corregir una idea, p. ej. 'X no es algo que se pueda conseguir con Y'.","絕對不是…的 means 'is definitely not something that…'. It uses the 是…的 frame with 絕對 for a very strong denial, often to correct an idea, e.g. 'X is not something Y can buy'."],"5-6-0":["Desde la postura de…","From the standpoint of…","","「站在…的立場」是「從某人的位置和想法來看事情」，常接「考慮、想、看」，語氣偏正式。","「站在…的立场」是「从某人的位置和想法来看事情」，常接「考虑、想、看」，语气偏正式。","站在 X 的立場 = ponerse en el lugar de X, ver el asunto desde su posición. Suele ir con 考慮／想／看 y es de registro algo formal; no significa «estar de pie en un lugar».","站在…的立場 means to look at an issue from someone's position and way of thinking. It is often followed by verbs like 考慮, 想 or 看 and is somewhat formal."],"5-6-1":["Tomar … como ejemplo","Take … as an example","","「以…為例」用在說明一般情況之後，舉出一個具體的例子，通常放在句首，後面加逗號。","「以…为例」用在说明一般情况之后，举出一个具体的例子，通常放在句首，后面加逗号。","以 X 為例 = tomando X como ejemplo. Se usa después de una afirmación general para dar un caso concreto; suele ir al inicio de la oración, seguido de coma. Es más formal que 比如說.","以…為例 introduces a concrete example after a general statement. It usually comes at the beginning of a sentence followed by a comma."],"5-6-2":["En otras palabras","In other words","","「換句話說」用另一種說法重新解釋前面的話，放在後一句句首，後面加逗號。","「换句话说」用另一种说法重新解释前面的话，放在后一句句首，后面加逗号。","換句話說 = en otras palabras, dicho de otro modo. Reformula o aclara lo dicho antes; va al inicio de la segunda oración, seguido de coma. Aparece tanto en habla como en escritura.","換句話說 restates the previous idea in different words. It is placed at the start of the next sentence, followed by a comma."],"5-6-3":["Comparado con A, B es más…","Compared with A, B is more…","","「和A比起來，B比較…」用A當標準來比較B，後面常接「比較、更、…得多」；「相較於」比較正式，意思相近。","「和A比起来，B比较…」用A当标准来比较B，后面常接「比较、更、…得多」；「相较于」比较正式，意思相近。","和 A 比起來，B 比較… = comparado con A, B es más…. «比起來» introduce el punto de referencia y el adjetivo va con 比較／更／得多, no con 比 otra vez. Se puede sustituir por 相較於 (más formal), como en el ejemplo.","和A比起來，B比較… compares B against A as a reference point; the predicate usually uses 比較, 更 or …得多. 相較於 is a more formal alternative with a similar meaning."],"5-6-4":["A menos que A, de lo contrario B","Unless A, otherwise B","","「除非A，不然B」表示只有做到A才能避免B，B通常是不好的結果；「不然」可換成較正式的「否則」。","「除非A，不然B」表示只有做到A才能避免B，B通常是不好的结果；「不然」可换成较正式的「否则」。","除非 A，不然 B = a menos que ocurra A, de lo contrario B. A es la única condición para evitar B, y B suele ser un resultado negativo. «不然» puede cambiarse por 否則 (más formal).","除非A，不然B means B will happen unless A is met; A is the only way to avoid B, and B is usually a bad outcome. 不然 can be replaced by the more formal 否則."],"5-6-5":["Verse / parecer (por contraste)","To appear / look (in contrast)","","「顯得」表示因為情況或對比，而給人某種樣子或印象，後面接形容詞或動詞，常搭配「特別、很、格外」。","「显得」表示因为情况或对比，而给人某种样子或印象，后面接形容词或动词，常搭配「特别、很、格外」。","顯得 = verse, parecer, dar la impresión de. Describe la impresión que algo o alguien da por la situación o por contraste; va seguido de adjetivo o verbo y suele llevar 特別／很／格外. No se usa para opiniones personales («yo creo que»).","顯得 means to look or appear a certain way because of the situation or by contrast. It is followed by an adjective or verb and often used with 特別, 很 or 格外."],"5-6-6":["Tener el lado de…","To have a … side","","「有…的一面」用來說明事情的某一個方面，常成對使用，例如「有好的一面，也有壞的一面」，常見於議論文。","「有…的一面」用来说明事情的某一个方面，常成对使用，例如「有好的一面，也有坏的一面」，常见于议论文。","有…的一面 = tener un lado/aspecto… Sirve para presentar una faceta de algo, a menudo en pares: 有好的一面，也有壞的一面. Es neutral y común en textos argumentativos.","有…的一面 presents one side or aspect of something and is often used in pairs, such as 有好的一面，也有壞的一面. It is common in argumentative writing."],"5-6-7":["Es decir","That is to say","","「也就是說」根據前面的內容做出結論或解釋，常接計算或推論的結果；和只重新說明的「換句話說」稍有不同。","「也就是说」根据前面的内容做出结论或解释，常接计算或推论的结果；和只重新说明的「换句话说」稍有不同。","也就是說 = es decir, o sea. Saca una conclusión o aclara el significado a partir de lo anterior (a veces con un cálculo). Se diferencia de 換句話說, que solo reformula; 也就是說 suele ir seguido del resultado.","也就是說 draws a conclusion or clarification from what was just said, often after a calculation. It differs slightly from 換句話說, which only restates."],"5-6-8":["Solo si A, entonces B","Only if A, then B","","「唯有A，才B」和「只有A才B」意思相同，但語氣更強、較書面，後半句要用「才」。","「唯有A，才B」和「只有A才B」意思相同，但语气更强、较书面，后半句要用「才」。","唯有 A，才 B = solo si A, entonces B. Equivale a 只有 A 才 B, pero es más enfático y de registro escrito/formal. «才» es obligatorio en la segunda parte.","唯有A，才B is the same as 只有A才B but more emphatic and literary. 才 is required in the second clause."],"5-7-0":["Romperse la cabeza por…","To rack one's brains over…","","「為了…傷腦筋」表示為了某件事想不出好辦法、很煩惱，「傷腦筋」是口語說法。","「为了…伤脑筋」表示为了某件事想不出好办法、很烦恼，「伤脑筋」是口语说法。","為了 X 傷腦筋 = preocuparse / romperse la cabeza por X. 傷腦筋 es coloquial y significa «dar dolor de cabeza» (un problema difícil de resolver). X es el asunto que preocupa.","為了…傷腦筋 means to rack one's brains or be troubled over something. 傷腦筋 is colloquial for 'giving someone a headache'."],"5-7-1":["No como A, sino B","Not like A, but B","","「不像A，而是B」用A（一般的、大家以為的）和B（實際的）作對比，「而是」帶出真正的情況。","「不像A，而是B」用A（一般的、大家以为的）和B（实际的）作对比，「而是」带出真正的情况。","不像 A，而是 B = no como A, sino B. Contrasta la forma o el modo: A es lo esperado o habitual y B es lo que realmente ocurre. «而是» introduce la corrección.","不像A，而是B contrasts what is usual or expected (A) with what is actually the case (B). 而是 introduces the correction."],"5-7-2":["A equivale a B","A is equivalent to B","","「A等同於B」表示A和B相同、沒有差別，語氣正式，常用來下很強的判斷。","「A等同于B」表示A和B相同、没有差别，语气正式，常用来下很强的判断。","A 等同於 B = A equivale a B, es lo mismo que B. Es formal y a menudo expresa un juicio fuerte (por ejemplo, «X equivale a un suicidio»). Más neutro que 無異於, que es más retórico.","A等同於B means A is the same as B. It is formal and often used for strong judgments."],"5-7-3":["La razón por la que A… radica en B","The reason A … lies in B","","「A之所以…，就在於B」先說結果（A…），再說原因（B），語氣正式，常用在解釋原因。","「A之所以…，就在于B」先说结果（A…），再说原因（B），语气正式，常用在解释原因。","A 之所以… 就在於 B = la razón por la que A…, radica en B. «之所以» presenta el resultado y «在於» la causa. Es formal y se usa en explicaciones; no se puede usar «因為» en la misma estructura.","A之所以…就在於B states a result first (之所以) and then its reason (在於). It is formal and used for explanations."],"5-7-4":["Desde la perspectiva de… (analizar)","From the perspective of… (+V)","","「從…的角度來+V」說明從哪一個方面或立場看事情，動詞常用「看、想、思考、分析」。","「从…的角度来+V」说明从哪一个方面或立场看事情，动词常用「看、想、思考、分析」。","從 X 的角度來 + V = desde la perspectiva de X (ver/pensar/analizar). Los verbos habituales son 看、想、思考、分析. Presenta el punto de vista desde el que se juzga algo; es de registro formal.","從…的角度來+V states the viewpoint from which something is seen. Common verbs are 看, 想, 思考 and 分析."],"5-7-5":["Hacer B por (el fin de) A","Do B for the sake of A","","「為了A而B」表示為了A這個目的或原因，做B這件事；「而」是連接詞，語氣較正式，常用「不應該為了A而B」。","「为了A而B」表示为了A这个目的或原因，做B这件事；「而」是连接词，语气较正式，常用「不应该为了A而B」。","為了 A 而 B = hacer B con el fin de A / por A. A es el propósito o motivo y B la acción. «而» conecta ambas partes y es de registro formal. Se usa mucho en negativo: 不應該為了 A 而 B.","為了A而B means doing B for the sake or purpose of A. 而 is a formal connector, and the negative form 不應該為了A而B is common."],"5-7-6":["Verse obligado a + V","To be forced to + V","","「被迫＋VP」表示在不得已的情況下，不得不做某事，通常不說是誰逼的，帶有違反意願的意思。","「被迫＋VP」表示在不得已的情况下，不得不做某事，通常不说是谁逼的，带有违反意愿的意思。","被迫 + V = verse obligado a hacer algo. Es una pasiva sin agente: no se menciona quién obliga y el resultado es contra la voluntad del sujeto. Se usa en contextos formales o de noticias.","被迫+VP means being forced to do something against one's will. The one who forces is usually not mentioned."],"5-7-7":["Si A todavía está por B","Whether A still awaits B","","「是否A還有待B」表示A是不是成立，還需要再B（例如觀察、研究）才能知道；「是否」是書面語，等於「是不是」。","「是否A还有待B」表示A是不是成立，还需要再B（例如观察、研究）才能知道；「是否」是书面语，等于「是不是」。","是否 A 還有待 B = si A todavía está por (ser) B. «是否» es la forma escrita de 是不是 y 有待 + verbo significa «queda pendiente de, requiere». B suele ser 觀察／研究／證實. Muy formal.","是否A還有待B means whether A is true still needs B (such as observation or study). 是否 is the written form of 是不是, and 有待 means 'remains to be'."],"5-8-0":["Convertir A en B","To turn A into B","","「化A為B」是把A轉變成B，語氣書面，A、B常是抽象名詞，例如「化危機為轉機」「化悲憤為力量」。","「化A为B」是把A转变成B，语气书面，A、B常是抽象名词，例如「化危机为转机」「化悲愤为力量」。","化 A 為 B = convertir A en B. Es una estructura formal/literaria; A y B suelen ser sustantivos abstractos opuestos o relacionados (化危機為轉機, 化悲憤為力量). Pertenece sobre todo a la lengua escrita.","化A為B means to transform A into B. It is literary, and A and B are usually abstract nouns, as in 化危機為轉機."],"5-8-1":["Según las estadísticas / los datos de…","According to the statistics / data of…","","「根據…的統計」「根據…的資料顯示」用來說明數字或結論的來源，常見於新聞和報告。","「根据…的统计」「根据…的资料显示」用来说明数字或结论的来源，常见于新闻和报告。","根據…的統計／資料顯示 = según las estadísticas (los datos) de…. Introduce la fuente de una cifra o conclusión y es muy común en noticias e informes. La parte «顯示» va antes de la conclusión.","根據…的統計／資料顯示 cites the source of figures or conclusions and is common in news and reports."],"5-8-2":["Siempre (hasta ahora), desde siempre","Always (all along), has always been","","「向來」表示從以前到現在一直是這樣，用在習慣或特點上，不用在未來或只發生一次的事。","「向来」表示从以前到现在一直是这样，用在习惯或特点上，不用在未来或只发生一次的事。","向來 = siempre, desde siempre. Indica algo que ha sido así de manera constante hasta el presente. Se usa con hechos habituales o características; no se usa con acciones futuras ni de una sola vez.","向來 means 'always, all along up to now'. It is used for habits or characteristics, not for future or one-time events."],"5-8-3":["A tiene prioridad sobre B","A takes priority over B","","「A優先於B」表示A比B更重要、要先處理；「於」是書面語，用來比較。","「A优先于B」表示A比B更重要、要先处理；「于」是书面语，用来比较。","A 優先於 B = A tiene prioridad sobre B. «於» marca la comparación en el estilo formal. Se usa para decir qué se pone primero cuando hay dos valores en conflicto.","A優先於B means A comes before B in importance. 於 is a literary comparison marker."],"5-8-4":["No es más que… / solo…","Nothing more than… / just…","","「只不過…罷了」表示事情沒那麼嚴重或不複雜，「罷了」放在句尾，用來把事情說得很輕。","「只不过…罢了」表示事情没那么严重或不复杂，「罢了」放在句尾，用来把事情说得很轻。","只不過…罷了 = no es más que…, solo…. Minimiza algo: «solo es», «nada más». 罷了 va al final de la oración. Suele usarse para restarle importancia o para explicar que la diferencia es pequeña.","只不過…罷了 downplays something, meaning 'it's nothing more than…'. 罷了 goes at the end of the sentence."],"5-8-5":["A y B están estrechamente relacionados","A and B are closely related","","「A與B息息相關」表示A和B關係非常密切、互相影響；「與」比較正式。","「A与B息息相关」表示A和B关系非常密切、互相影响；「与」比较正式。","A 與 B 息息相關 = A y B están estrechamente relacionados. «息息» refuerza «相關» (el uno afecta al otro continuamente). «與» es la forma formal de 和／跟. Se usa en textos formales.","A與B息息相關 means A and B are very closely connected and affect each other. 與 is the formal version of 和／跟."],"5-9-0":["A, B e incluso C","A, B and even C","","「A、B乃至（於）C」把範圍由小到大列出來，C是最大或最極端的，語氣正式，「於」可以省略。","「A、B乃至（于）C」把范围由小到大列出来，C是最大或最极端的，语气正式，「于」可以省略。","A、B 乃至（於）C = A, B e incluso C. Enumera elementos de alcance creciente: C es el más amplio o el más extremo. Es formal, propio de la lengua escrita; «於» es opcional.","A、B乃至（於）C lists items of increasing scope, with C the widest or most extreme. It is formal and 於 is optional."],"5-9-1":["A; también se puede decir que B","A; one could also say B","","「A，也可以說B」先說一個說法A，再補上另一個常常更強或帶評價的說法B。","「A，也可以说B」先说一个说法A，再补上另一个常常更强或带评价的说法B。","A，也可以說（是）B = A; también se puede decir que B. Ofrece una segunda formulación, a menudo más fuerte o más valorativa que la primera. Va después de una coma, sin cambiar de sujeto.","A，也可以說B gives a second way of putting it, often stronger or more evaluative than the first."],"5-9-2":["Cualquiera… (quien sea)","Anyone would…","","「任誰都…」意思是「不論是誰都…」，後面常接「都／也」，表示在那種情況下，每個人的反應都一樣。","「任谁都…」意思是「不论是谁都…」，后面常接「都／也」，表示在那种情况下，每个人的反应都一样。","任誰都 + V/adj = cualquiera, sea quien sea, … (en esa situación). «任誰» equivale a 不論是誰 y se combina con 都 o 也. El hablante da por hecho que la reacción es universal; es de registro algo formal.","任誰都… means 'no matter who it is, everyone would…'. It is usually followed by 都 or 也 and implies that anyone would react the same way."],"5-9-3":["Hacer frente a / responder a","To respond to / cope with","","「因應」是正式的動詞，表示針對某個情況或變化採取辦法，後面接情況，常說「為了因應…」。","「因应」是正式的动词，表示针对某个情况或变化采取办法，后面接情况，常说「为了因应…」。","因應 = hacer frente a, responder a un cambio o situación. Es un verbo formal que lleva como objeto la situación a la que se responde (因應需求、因應變化); se usa mucho con 為了 al inicio.","因應 is a formal verb meaning to respond to or cope with a situation or change. It is often used as 為了因應…."],"5-9-4":["Comparado con B, A…","Compared with B, A…","","「A與B相比，…」是「A和B比起來」的正式說法，先說A，再說比較的結果，常出現在說明數字的文章裡。","「A与B相比，…」是「A和B比起来」的正式说法，先说A，再说比较的结果，常出现在说明数字的文章里。","A 與 B 相比，… = comparado con B, A…. Forma formal de «A 和 B 比起來». Primero se presenta el tema A, luego se da el resultado de la comparación (con números o adjetivos). «與» es de registro escrito.","A與B相比，… is the formal version of A和B比起來. It states the topic A and then the result of the comparison, often with figures."],"5-9-5":["Mucho más/menos … que…","Far more/less … than…","","「遠＋V於…」表示「比…高很多／低很多」，常見的有「遠高於、遠低於、遠大於、遠多於」，不需要再用「比」，多用在書面語。","「远＋V于…」表示「比…高很多／低很多」，常见的有「远高于、远低于、远大于、远多于」，不需要再用「比」，多用在书面语。","遠 + V於… = mucho más/menos … que…. Se forma con 遠 + adjetivo + 於 (遠高於、遠低於、遠大於、遠多於). «於» marca la comparación, por eso no se usa 比 ni 很. Es propio de textos escritos con cifras.","遠V於… means 'far more/less than…', as in 遠高於, 遠低於, 遠大於, 遠多於. 於 marks the comparison, so 比 is not needed. It is used in written texts."],"5-9-6":["Por A, hay cierto B","Because of A, there is some B","","「受A而有所B」表示因為受到A的影響，而在某種程度上B；「有所」後面常接兩個字的詞，例如「顧慮、改變、不同」。","「受A而有所B」表示因为受到A的影响，而在某种程度上B；「有所」后面常接两个字的词，例如「顾虑、改变、不同」。","受 A 而有所 B = por verse afectado por A, hay cierto B. «有所» + verbo de dos sílabas (顧慮、改變、不同、改善) expresa «en cierta medida». A es el factor que influye. Formal.","受A而有所B means that being affected by A leads to some degree of B. 有所 is usually followed by a two-character word like 顧慮, 改變 or 不同."],"5-10-0":["A y B están del mismo lado","A and B stand on the same side","","「A跟B站在同一陣線」表示A和B立場一致、互相支持；「陣線」原本是戰爭用語，這裡是比喻。","「A跟B站在同一阵线」表示A和B立场一致、互相支持；「阵线」原本是战争用语，这里是比喻。","A 跟 B 站在同一陣線 = A y B están del mismo lado (en el mismo frente). 陣線 es «frente, bando»; se usa en sentido figurado para quien apoya la misma causa. Puede ir con 和 o 跟.","A跟B站在同一陣線 means A and B are on the same side and support each other. 陣線 originally means a battle line and is used figuratively here."],"5-10-1":["A no se diferencia de B","A is no different from B","","「A和B沒有兩樣」表示A和B看不出差別，常搭配「看起來、吃起來」，有時帶一點驚訝或批評的意思。","「A和B没有两样」表示A和B看不出差别，常搭配「看起来、吃起来」，有时带一点惊讶或批评的意思。","A 和（跟）B 沒有兩樣 = A no se diferencia de B, es igual que B. «沒有兩樣» = no hay diferencia; se usa a menudo con 看起來／吃起來／聽起來 para impresiones. Suele implicar sorpresa o crítica.","A和（跟）B沒有兩樣 means A is no different from B. It is often used with 看起來 or 吃起來 and may carry surprise or criticism."],"5-10-2":["A no tiene que ver con B","A has nothing to do with B","","「A與B無關」表示A和B沒有關係；「與」較正式，「跟」較口語，常用來否認原因或責任。","「A与B无关」表示A和B没有关系；「与」较正式，「跟」较口语，常用来否认原因或责任。","A 與（跟）B 無關 = A no tiene nada que ver con B. «無關» = 沒有關係, más formal; «與» es formal y «跟» coloquial. Se usa para negar una relación causal o de responsabilidad.","A與（跟）B無關 means A has no connection to B. 與 is formal while 跟 is colloquial; it is often used to deny causes or responsibility."],"5-10-3":["Unir / vincular A con B","To link A and B together","","「把A跟B連在一起」是把兩件事聯繫起來看，用「把」字句，常見的否定說法是「不要把A跟B連在一起」。","「把A跟B连在一起」是把两件事联系起来看，用「把」字句，常见的否定说法是「不要把A跟B连在一起」。","把 A 跟 B 連在一起 = unir/vincular A con B (en la mente, en los hechos o en la política). Usa la estructura 把 con el resultado «連在一起». Con frecuencia aparece en negativo: 不要把 A 跟 B 連在一起.","把A跟B連在一起 means to link two things together, mentally or in practice. It is a 把 sentence and often appears negatively, as 不要把A跟B連在一起."],"5-10-4":["Usar … como lema","To use … as a slogan","","「以…做為口號」是把某句話當作口號，常用在政治、社會運動或宣傳；「以…做為…」比較正式。","「以…做为口号」是把某句话当作口号，常用在政治、社会运动或宣传；「以…做为…」比较正式。","以 X 做為口號 = usar X como lema/consigna. 以…做為… es una estructura formal («tomar X como Y»); 口號 es un eslogan que un grupo repite para movilizar o convencer. Se usa en política y campañas.","以…做為口號 means to use a phrase as a slogan, often in politics, campaigns and social movements. 以…做為… is a formal pattern."],"5-10-5":["Hacer caso omiso de… (N)","To disregard the N of…","","「無視…的N」表示故意不理會，常接「權益、安全、感受」等名詞，語氣帶批評，多用在新聞和評論。","「无视…的N」表示故意不理会，常接「权益、安全、感受」等名词，语气带批评，多用在新闻和评论。","無視 X 的 N = hacer caso omiso de / ignorar a propósito el N de X (權益、安全、感受). Implica ignorarlo deliberadamente y tiene un tono de crítica. Es formal y se usa en noticias y comentarios.","無視…的N means to deliberately disregard something, such as someone's rights, safety or feelings. It has a critical tone and is used in news and commentary."],"5-10-6":["A no es otra cosa que B","A is no different from B","","「A，無異於B」表示A和B沒有差別，常用來強烈批評或比喻（例如「無異於自殺」），比「等同於」語氣更強，較書面。","「A，无异于B」表示A和B没有差别，常用来强烈批评或比喻（例如「无异于自杀」），比「等同于」语气更强，较书面。","A，無異（於）B = A no es otra cosa que B, equivale a B. Es una comparación retórica y a menudo negativa (無異於自殺, 無異於強盜). Es más fuerte que 等同於, que solo indica equivalencia. Registro formal.","A，無異（於）B says A is no different from B, usually as a strong or negative comparison. It is stronger than 等同於 and is literary."],"5-10-7":["A depende de B","A depends on B","","「A，有賴B」表示要做成A，需要依靠B；「有賴」是書面語，常說「有賴大家的努力」。","「A，有赖B」表示要做成A，需要依靠B；「有赖」是书面语，常说「有赖大家的努力」。","A，有賴 B = A depende de B (se necesita B). «有賴» = 依靠, formal; B es la persona o el factor que se necesita para lograr A. Aparece mucho en frases como 有賴大家的努力.","A，有賴B means A relies on B to be achieved. 有賴 is literary, as in 有賴大家的努力."],"6-1-0":["Mirar al panorama: 放眼","Looking across: 放眼","","「放眼」是「把目光放遠、放寬來看」的意思，後面接範圍大的名詞（世界、未來、全球），再說明看到的趨勢。多用在書面或演講。","「放眼」是「把目光放远、放宽来看」的意思，后面接范围大的名词（世界、未来、全球），再说明看到的趋势。多用在书面或演讲。","放眼 + ámbito amplio (世界, 未來, 二十一世紀) = «si se mira / abarcando con la vista…». Registro formal y escrito; abre la oración y después se comenta una tendencia o conclusión.","放眼 means 'to cast one's eyes broadly over…'. It is followed by a wide scope (the world, the future, the 21st century) and then a trend or conclusion. Formal, written or speech style."],"6-1-1":["Lo importante de X radica en Y","The key point of X lies in Y","","用來指出某件事的重點、特別或困難「就在於」什麼。「……之處」前面常放「重要、特別、困難、可貴」等詞，語氣比較正式。","用来指出某件事的重点、特别或困难「就在于」什么。「……之处」前面常放「重要、特别、困难、可贵」等词，语气比较正式。","X 之處，在於 Y = «lo (importante / especial / difícil) de X radica en Y». Se usa para señalar dónde está el punto clave; adjetivos típicos: 重要、特別、困難、可貴. Registro formal.","'The important/special/difficult point of X lies in Y.' The part before 之處 is usually 重要, 特別, 困難 or 可貴. Fairly formal."],"6-1-2":["Competir por hacer algo: 爭相","Vying to do something: 爭相","Vying to do something: 争相","「爭相＋動詞」表示很多人搶著做某件事，主詞通常是一群人，多用在書面語。","「争相＋动词」表示很多人抢着做某件事，主词通常是一群人，多用在书面语。","爭相 + verbo = hacer algo a porfía, peleándose por ser el primero. El sujeto suele ser plural (mucha gente). Registro formal/escrito.","爭相 + verb means many people compete or rush to do something. The subject is usually a group. Mostly written style."],"6-1-3":["Siendo (rol): 身為","As (a role): 身為","As (a role): 身为","「身為＋身分」表示「作為某種身分的人」，後面常接這個身分應該做的事，例如「應該、必須、要」。","「身为＋身分」表示「作为某种身分的人」，后面常接这个身分应该做的事，例如「应该、必须、要」。","身為 + identidad o rol = «siendo / como (tal cosa)». Introduce una responsabilidad o expectativa ligada a ese rol; después suelen aparecer 應該、必須、要.","身為 + role means 'being / as a (role)'. What follows is usually a duty or expectation of that role, often with 應該, 必須 or 要."],"6-1-4":["Al contrario, fue…: 反而是","On the contrary, it was…: 反而是","","先說一個情況，再用「反而是」帶出和預期相反、出乎意料的結果，重點放在後面的 B。","先说一个情况，再用「反而是」带出和预期相反、出乎意料的结果，重点放在后面的 B。","A，反而是 B = «pero, al contrario, fue B (lo que…)». Señala un resultado inesperado o contrario a lo que se esperaba, poniendo énfasis en B. Se puede decir también solo 反而.","After stating a situation, 反而是 introduces the unexpected or opposite result, stressing B."],"6-1-5":["Año tras año: 逐年","Year by year: 逐年","","「逐年」是「一年一年地」的意思，後面常接增加、減少等變化，多用在書面語。類似的詞還有「逐漸、逐步、逐日」。","「逐年」是「一年一年地」的意思，后面常接增加、减少等变化，多用在书面语。类似的词还有「逐渐、逐步、逐日」。","逐年 + verbo/cambio = «año tras año, cada año más». Registro formal; relacionados: 逐漸 (poco a poco), 逐步 (paso a paso), 逐日 (día a día).","逐年 means 'year by year' and is followed by a change such as an increase or decrease. Formal. Similar words: 逐漸, 逐步, 逐日."],"6-1-6":["Orientar A de X hacia Y: 將A轉向Y","Shift A (from X) toward Y","","表示把 A（從原本的 X）改變方向，轉到 Y。「將」就是書面語的「把」，「從 X」可以省略。","表示把 A（从原本的 X）改变方向，转到 Y。「将」就是书面语的「把」，「从 X」可以省略。","將 A（從 X）轉向 Y = «desplazar A (de X) hacia Y». 將 equivale a 把 en el registro escrito; X (de dónde viene) es opcional.","'To shift A (from X) toward Y.' 將 is the written form of 把; 從X can be omitted."],"6-1-7":["Limitarse a: 自限於","Confine oneself to: 自限於","Confine oneself to: 自限于","「自限於 X」是「把自己限制在 X 的範圍裡」，常用來勸人不要被學歷、經驗、想法綁住。語氣較正式。","「自限于 X」是「把自己限制在 X 的范围里」，常用来劝人不要被学历、经验、想法绑住。语气较正式。","自限於 + X = «limitarse a / encerrarse uno mismo en X» (título, experiencia, ideas). Tono crítico o de consejo; registro formal.","自限於 X means 'to limit oneself to X' (qualifications, experience, ideas), often used critically or as advice. Formal."],"6-1-8":["Obligar a: 迫使","Force / compel: 迫使","","「A 迫使 B＋動詞」表示因為某種情況或壓力，讓 B 不得不做某件事。主詞通常是情況（汙染、不景氣），不是下命令的人。","「A 迫使 B＋动词」表示因为某种情况或压力，让 B 不得不做某件事。主词通常是情况（污染、不景气），不是下命令的人。","A 迫使 B + verbo = «A obliga a B a…». El sujeto es una circunstancia o presión (la contaminación, la crisis…), no una persona que da una orden; B no tiene opción. Registro formal.","A 迫使 B + verb: a situation or pressure (pollution, recession) leaves B no choice but to do something. Formal."],"6-1-9":["Empezar a base de: 靠……起家","Start from / rise through …","","「靠 X 起家」是說憑著 X 從無到有、慢慢發展起來，X 常是一種生意或技能。","「靠 X 起家」是说凭着 X 从无到有、慢慢发展起来，X 常是一种生意或技能。","靠 X 起家 = «levantarse (un negocio, una familia) a base de X», es decir, haber empezado desde abajo gracias a X. Registro neutro-escrito; X suele ser un negocio o un oficio.","靠 X 起家 means to build up a business or family fortune starting from X; X is usually a trade or a skill."],"6-2-0":["Partir de X: 從X出發","Starting from X","","「從 X 出發」是「以 X 為起點或基礎」，X 常是需要、角度、經驗。字面上也能指「從某地出發」。","「从 X 出发」是「以 X 为起点或基础」，X 常是需要、角度、经验。字面上也能指「从某地出发」。","從 X 出發 = «partir de X» (una necesidad, un punto de vista, la experiencia). También tiene el sentido literal de «salir desde un lugar» (從台北出發). Aquí es el sentido figurado.","從 X 出發 means 'to start from X' (a need, a viewpoint, experience). It can also mean literally 'to set out from a place'."],"6-2-1":["Llegar a la cifra de: 有X之多","As many as X","","「有＋數量＋之多」強調數量很大，比想像的還多，常和「竟然」一起用。","「有＋数量＋之多」强调数量很大，比想像的还多，常和「竟然」一起用。","有 + cantidad + 之多 = «llegar a haber nada menos que…». Subraya que la cantidad es mayor de lo que se esperaría; suele combinarse con 竟然 o 高達.","有 + quantity + 之多 stresses that the amount is larger than expected ('as many as…'); often used with 竟然."],"6-2-2":["Proviene de: 出自","Come from / originate from: 出自","","「出自 X」表示來源是 X，常指文章、作者、典籍、歷史故事等，可用來說明某句話或某個故事的出處。","「出自 X」表示来源是 X，常指文章、作者、典籍、历史故事等，可用来说明某句话或某个故事的出处。","出自 + origen = «proviene de» (una obra, un autor, un libro clásico, la boca de alguien). Sirve para citar la fuente de una frase, una historia o una idea. Formal-neutro.","出自 X means 'originates from X' (a work, an author, a classic, a historical story), used to cite a source."],"6-2-3":["Y así, por lo cual: 從而","Thereby: 從而","Thereby: 从而","「A，從而 B」表示 B 是由 A 帶來的結果或目的，兩句通常是同一個主詞。只用在書面語。","「A，从而 B」表示 B 是由 A 带来的结果或目的，两句通常是同一个主词。只用在书面语。","A，從而 B = «A, y así / con lo cual B». Une dos cláusulas con el mismo sujeto: B es el resultado o el propósito de A. Solo se usa en el lenguaje escrito o formal.","A，從而 B means 'A, thereby B': B is the result or purpose of A, usually with the same subject. Written/formal only."],"6-2-4":["Estar acostumbrado a X: 對X習以為常","Take X for granted","","「對 X 習以為常」是對 X 已經很習慣，不覺得奇怪或特別。","「对 X 习以为常」是对 X 已经很习惯，不觉得奇怪或特别。","對 X 習以為常 = «estar tan acostumbrado a X que ya no resulta extraño». Implica que algo que a otros les parecería raro ya es normal para esa persona.","對 X 習以為常 means to be so used to X that it no longer seems strange."],"6-2-5":["Formar Y con X: 利用X組成Y","Use X to form Y","","「利用 X 組成 Y」是用 X 當材料或工具，組合成 Y。X 是材料，Y 是完成的東西。","「利用 X 组成 Y」是用 X 当材料或工具，组合成 Y。X 是材料，Y 是完成的东西。","利用 X 組成 Y = «usar X para formar / armar Y». X es el material y Y es el resultado; se dice 利用 antes de 組成 para indicar el medio.","利用 X 組成 Y: using X as the material to put together Y."],"6-2-6":["Equivale a: 等於是","Is equivalent to: 等於是","Is equivalent to: 等于是","「A 等於是 B」表示說話者認為 A 就和 B 一樣，常帶有誇張或批評的語氣。類似的說法有「就等於、無異於」。","「A 等于是 B」表示说话者认为 A 就和 B 一样，常带有夸张或批评的语气。类似的说法有「就等于、无异于」。","A 等於是 B = «A equivale a B / es como B». Es un juicio subjetivo que presenta A como lo mismo que B, a menudo con tono exagerado o crítico. Sinónimo: 就等於、無異於.","A 等於是 B means the speaker sees A as the same as B, often with an exaggerated or critical tone. Similar: 就等於, 無異於."],"6-3-0":["Sin reservas: 盡情","To one's heart's content: 盡情","To one's heart's content: 尽情","「盡情＋動詞」是毫無保留、盡量地做某件事，常見搭配有盡情享受、盡情玩、盡情唱歌。它是副詞，放在動詞前面。","「尽情＋动词」是毫无保留、尽量地做某件事，常见搭配有尽情享受、尽情玩、尽情唱歌。它是副词，放在动词前面。","盡情 + verbo = hacer algo sin reservas, a todo gusto (盡情享受、盡情玩、盡情唱). Es un adverbio que va antes del verbo; expresa que se disfruta sin contenerse.","盡情 is an adverb placed before a verb: to do something wholeheartedly, without holding back (盡情享受, 盡情玩, 盡情唱歌)."],"6-3-1":["En calidad de: 以X（的）身分","In the capacity of X","","「以 X（的）身分」表示用 X 的立場或角色來做事或說話，例如代表、旁觀者、朋友。","「以 X（的）身分」表示用 X 的立场或角色来做事或说话，例如代表、旁观者、朋友。","以 X（的）身分 + verbo = «en calidad de / como X». Indica el papel o posición desde el que se actúa o se habla (representante, testigo, observador…).","以 X（的）身分 means 'in the capacity / role of X' — the position from which someone acts or speaks."],"6-3-2":["Hacer un «gran encuentro» de X y Y: 來個X大會Y","Hold a big 'X meets Y'","","「來個 X 大會 Y」是一種有點幽默的口語說法，意思像「來辦一場 X 和 Y 的大會面（大聚會）」，用來讓句子比較活潑，不是很固定的句型。","「来个 X 大会 Y」是一种有点幽默的口语说法，意思像「来办一场 X 和 Y 的大会面（大聚会）」，用来让句子比较活泼，不是很固定的句型。","來個 X 大會 Y = forma humorística y coloquial de «organizar un gran encuentro entre X y Y» (aquí 會 es «reunirse»). Se usa para dar un toque juguetón a la frase; es creativa, no una estructura rígida.","來個 X 大會 Y is a playful, colloquial pattern meaning roughly 'let's hold a big X-meets-Y gathering' (會 = to meet). It is a humorous coinage rather than a rigid structure."],"6-3-3":["X se convierte en Y: X化為Y","X turns into Y","","「X 化為 Y」是 X 變成了另一種東西 Y，比「變成」更書面。也可以說「把 X 化為 Y」。","「X 化为 Y」是 X 变成了另一种东西 Y，比「变成」更书面。也可以说「把 X 化为 Y」。","X 化為 Y = «X se transforma en Y». Muestra un cambio de naturaleza o forma (basura → recursos, tristeza → fuerza). 化為 es más escrito que 變成. También se usa 把 X 化為 Y.","X 化為 Y means X is transformed into Y (waste → resources, grief → strength). More written than 變成; also 把 X 化為 Y."],"6-3-4":["En el instante en que: 在……（的）剎那","At the instant when…","","「在……（的）剎那」指某件事發生的那一瞬間，很短暫，語氣有點文學或戲劇性。","「在……（的）刹那」指某件事发生的那一瞬间，很短暂，语气有点文学或戏剧性。","在 + evento + （的）剎那 = «en el instante en que…». Marca un momento muy breve en el que ocurre algo importante; es literario y dramático. Se puede abreviar como 在…剎那.","在…（的）剎那 means 'at the very instant when…', a brief, dramatic moment. Literary tone."],"6-3-5":["Tarde o temprano: 終會……的","In the end will surely…: 終會…的","In the end will surely…: 终会…的","「終會……的」表示相信將來一定會有某個結果，常和「只要」一起用，句尾的「的」加強肯定的語氣。","「终会……的」表示相信将来一定会有某个结果，常和「只要」一起用，句尾的「的」加强肯定的语气。","終會 + verbo + 的 = «tarde o temprano se… / al final seguramente…». Expresa confianza en un resultado futuro; suele ir con 只要 y se cierra con 的 para dar certeza.","終會…的 expresses confidence that something will surely happen in the end; often paired with 只要, with sentence-final 的 adding certainty."],"6-3-6":["Con solo mirar: 一眼就……","At a single glance: 一眼就…","","「一眼就……」表示一看就馬上知道或決定，例如一眼就看出、一眼就愛上。","「一眼就……」表示一看就马上知道或决定，例如一眼就看出、一眼就爱上。","一眼就 + verbo = «con solo echar un vistazo, enseguida…» (一眼就看出、一眼就愛上). Indica que algo se percibe o se decide muy rápido al ver.","一眼就… means 'at a single glance, immediately…' (一眼就看出, 一眼就愛上)."],"6-3-7":["Gracias a / basándose en: 憑","Relying on / by virtue of: 憑","Relying on / by virtue of: 凭","「憑＋條件」表示依靠或根據某種能力、努力、證據，後面說能做到的事。也可以用在反問：「憑什麼？」","「凭＋条件」表示依靠或根据某种能力、努力、证据，后面说能做到的事。也可以用在反问：「凭什么？」","憑 + condición (una habilidad, un esfuerzo, una prueba) = «gracias a / basándose en…». Después se presenta lo que se logra o se concluye. También se usa en preguntas retóricas: 憑什麼 «¿con qué derecho?».","憑 + condition means 'relying on / on the strength of' a skill, effort or evidence. Also in rhetorical questions: 憑什麼 'on what grounds?'."],"6-3-8":["Imponer sobre: 加諸（在）","Impose on: 加諸（在）","Impose on: 加诸（在）","「加諸（在）」就是「加在……身上」，常接壓力、責任、期望、痛苦等抽象的東西，語氣正式、書面。","「加诸（在）」就是「加在……身上」，常接压力、责任、期望、痛苦等抽象的东西，语气正式、书面。","加諸（在）+ persona = «imponer / cargar sobre». 加諸 = 加在…上 (諸 = 之於). Se usa con cosas abstractas negativas o pesadas: 壓力、責任、痛苦、期望. Registro formal y escrito.","加諸（在）means 'to impose upon / place on someone' (加諸 = 加在…上). Used with abstract burdens: pressure, responsibility, expectations, suffering. Formal."],"6-3-9":["¿Acaso no…?: 何嘗","How could it be that…not: 何嘗","How could it be that…not: 何尝","「何嘗」用來反問，最常見的是「何嘗不／何嘗沒……」，意思是「其實是……的」，說話者要表達的和字面相反。多用於書面或比較正式的場合。","「何尝」用来反问，最常见的是「何尝不／何尝没……」，意思是「其实是……的」，说话者要表达的和字面相反。多用于书面或比较正式的场合。","何嘗 introduce una pregunta retórica. Lo más común es 何嘗不／何嘗沒 + verbo = «¿cómo no iba a…?, en realidad sí…»; a veces 何嘗 + afirmativo implica «nada de eso». El hablante expresa en el fondo lo contrario a lo que parece. Registro escrito/formal.","何嘗 introduces a rhetorical question. Most common is 何嘗不／何嘗沒…, meaning 'it's not that I don't…; in fact I do'. The speaker means the opposite of the literal question. Written/formal."],"6-3-10":["Sin darse cuenta: 不自覺（地）","Unconsciously: 不自覺（地）","Unconsciously: 不自觉（地）","「不自覺（地）＋動詞」表示自己沒有注意到、不是故意地做了某個動作或反應，和「不知不覺」很接近。","「不自觉（地）＋动词」表示自己没有注意到、不是故意地做了某个动作或反应，和「不知不觉」很接近。","不自覺（地）+ verbo = «sin darse cuenta, de forma involuntaria». Describe una reacción o acción que ocurre sin decisión consciente; muy parecido a 不知不覺, pero más centrado en la acción del cuerpo o los gestos.","不自覺（地）+ verb means doing something without realizing it or meaning to; close to 不知不覺."],"6-4-0":["Compartir Y con X: 與X分享Y","Share Y with X","","「與 X 分享 Y」是和 X 一起分享 Y，「與」是書面語的「跟／和」，Y 常是好的事物，如快樂、幸運、經驗。","「与 X 分享 Y」是和 X 一起分享 Y，「与」是书面语的「跟／和」，Y 常是好的事物，如快乐、幸运、经验。","與 X 分享 Y = «compartir Y con X». 與 es la forma escrita de 跟/和; Y suele ser algo agradable (alegría, suerte, experiencia, fotos). Se puede invertir: 把 Y 與 X 分享.","與 X 分享 Y means 'to share Y with X'. 與 is the written form of 跟/和; Y is usually something good (joy, luck, experience)."],"6-4-1":["Vivir con la filosofía de…: 抱持著……的哲學","Hold the philosophy of…","","「抱持著……的哲學」是說一個人的生活態度像這句話一樣，中間常放一句短短的人生信條。「抱持」常接態度、信念，例如抱持希望、抱持懷疑。","「抱持着……的哲学」是说一个人的生活态度像这句话一样，中间常放一句短短的人生信条。「抱持」常接态度、信念，例如抱持希望、抱持怀疑。","抱持著 + «lema» + 的哲學 = «mantener la filosofía de…». Entre las comillas se pone una frase corta que resume la actitud de vida. 抱持 = mantener una actitud, creencia o expectativa (抱持希望、抱持懷疑).","抱持著…的哲學 means 'to hold the philosophy of…'; a short life motto goes in between. 抱持 takes attitudes and beliefs (抱持希望, 抱持懷疑)."],"6-4-2":["Dar el primer paso: 踏出……的第一步","Take the first step toward…","","「踏出……的第一步」是比喻說法，表示開始做某件重要的事情，例如踏出成功的第一步。","「踏出……的第一步」是比喻说法，表示开始做某件重要的事情，例如踏出成功的第一步。","踏出 + meta + 的第一步 = «dar el primer paso hacia / de…». Se usa en sentido figurado para el comienzo de un proceso o proyecto importante.","踏出…的第一步 is a figurative expression for starting something important ('take the first step of/toward…')."],"6-4-3":["Bien podrías: 不妨","Might as well: 不妨","","「不妨＋動詞」是一種客氣的建議，表示「這樣做也沒有壞處，可以試試看」，不是命令。","「不妨＋动词」是一种客气的建议，表示「这样做也没有坏处，可以试试看」，不是命令。","不妨 + verbo = «bien podrías / no está de más…». Es una sugerencia suave y amable: no es obligatoria y no hay inconveniente en hacerlo. No se usa para ordenar ni sobre uno mismo con tono de obligación.","不妨 + verb is a gentle suggestion: 'there's no harm in…, you might as well…'. It is not a command."],"6-4-4":["Haber margen para…: （沒）有……的餘地","(No) room for…","","「（沒）有……的餘地」表示（沒有）空間或機會可以做某件事，常見的有「沒有選擇的餘地、有改進的餘地、沒有討價還價的餘地」。","「（没）有……的余地」表示（没有）空间或机会可以做某件事，常见的有「没有选择的余地、有改进的余地、没有讨价还价的余地」。","（沒）有 + acción + 的餘地 = «(no) haber margen / espacio para…». 餘地 es el margen que queda para negociar, discutir o elegir. Frases típicas: 沒有討論的餘地、有改進的餘地、沒有選擇的餘地.","（沒）有…的餘地 means there is (no) room or leeway to do something, e.g. 沒有選擇的餘地, 有改進的餘地."],"6-4-5":["De modo que (resultado): 以致（於）","As a result / so that (bad outcome): 以致（於）","As a result / so that (bad outcome): 以致（于）","「A，以致（於）B」表示因為 A 而造成 B 這個結果，B 通常是不好的、不希望發生的結果。不能用來表示目的。","「A，以致（于）B」表示因为 A 而造成 B 这个结果，B 通常是不好的、不希望发生的结果。不能用来表示目的。","A，以致（於）B = «A, de modo que / con el resultado de que B». B es una consecuencia, casi siempre negativa o no deseada, de A. No se usa para expresar un propósito (para eso: 以便、為了).","A，以致（於）B: A leads to the result B, which is usually unfavorable. It cannot express purpose (use 以便 or 為了 instead)."],"6-4-6":["Es fácil imaginar: 可想而知","It's easy to imagine: 可想而知","","「可想而知」是說從前面的情況就能知道結果，不用多說，常放在句中或句尾，是固定說法。","「可想而知」是说从前面的情况就能知道结果，不用多说，常放在句中或句尾，是固定说法。","可想而知 = «se puede imaginar fácilmente / es de suponer». Va entre comas o al final para decir que la conclusión es obvia a partir de lo dicho. Registro escrito y de uso fijo.","可想而知 is a fixed phrase meaning 'it is easy to imagine / as one can imagine', concluding something obvious from what was said."],"6-4-7":["Nace de: 發自","Come from (within): 發自","Come from (within): 发自","「發自 X」表示從 X 發出來，常指感情從內心發出，固定說法有「發自內心、發自肺腑」。","「发自 X」表示从 X 发出来，常指感情从内心发出，固定说法有「发自内心、发自肺腑」。","發自 + origen = «nace de / proviene de» (un sentimiento que sale desde dentro). Colocaciones fijas: 發自內心、發自肺腑 (desde lo más profundo del corazón). Registro formal/escrito.","發自 X means 'to come from X', typically a feeling from within: 發自內心, 發自肺腑. Formal."],"6-4-8":["Poco después: 隨後","Soon afterwards: 隨後","Soon afterwards: 随后","「隨後」表示緊接著前一件事之後，常用在第二句，可說「隨後就……」。比「然後」正式。","「随后」表示紧接着前一件事之后，常用在第二句，可说「随后就……」。比「然后」正式。","隨後 = «luego, poco después, a continuación». Indica que un hecho sigue inmediatamente a otro; se usa en la segunda cláusula, a menudo con 就 (隨後就). Es más formal que 然後.","隨後 means 'soon after / right afterwards', used in the second clause (often 隨後就…). More formal than 然後."],"6-4-9":["Con eso, para…: 以此來……","Using this to…: 以此來…","Using this to…: 以此来…","「以此來＋動詞」表示拿前面說的事情（此）當作方法或根據，去做後面的事。語氣正式、書面。","「以此来＋动词」表示拿前面说的事情（此）当作方法或根据，去做后面的事。语气正式、书面。","以此來 + verbo = «usando esto para… / con ello para…». 此 recoge lo dicho antes (un hecho o criterio), y lo que sigue es el propósito o el método. Registro formal y escrito.","以此來 + verb means 'using this (what was just mentioned) to…', giving the method or purpose. Formal, written."],"6-4-10":["Gracias a la acumulación de…: 藉著……的累積","By means of the accumulation of…","","「藉著 X 的累積」表示靠著 X 一點一點累積起來，達到後面的結果。「藉著」是「憑藉」的意思，X 常是經驗、知識、時間。","「借着 X 的累积」表示靠着 X 一点一点累积起来，达到后面的结果。「借着」是「凭借」的意思，X 常是经验、知识、时间。","藉著 + X + 的累積 = «aprovechando / gracias a la acumulación de X» (經驗、知識、時間). 藉著 = «valiéndose de». Registro escrito; 累積 se combina con experiencia, riqueza, conocimiento.","藉著 X 的累積 means 'by means of the accumulation of X' (experience, knowledge, time). Written style."],"6-5-0":["Al enfrentarse a…: 面對……時","When faced with…","","「面對……時」表示遇到某種人、事、物的時候，後面說當時的反應或應該怎麼做。","「面对……时」表示遇到某种人、事、物的时候，后面说当时的反应或应该怎么做。","面對 + situación/cosa + 時 = «al enfrentarse a / ante…». Marca el momento en que se reacciona ante algo (una tentación, un problema, una decisión). Registro neutro-escrito.","面對…時 means 'when faced with…', followed by the reaction or the right way to respond."],"6-5-1":["Quedar atrapado en: 身陷……（裡）","Be trapped in…","","「身陷……」是自己被困在某個不好的環境或處境裡，不容易離開，例如身陷困境、身陷險境、身陷車海。","「身陷……」是自己被困在某个不好的环境或处境里，不容易离开，例如身陷困境、身陷险境、身陷车海。","身陷 + situación difícil (險境、困境、車海、債務) = «estar metido / atrapado en…». Se usa para situaciones de las que cuesta salir; se puede añadir 裡 con lugares o espacios.","身陷… means being trapped in a bad situation that is hard to escape: 身陷困境, 身陷險境, 身陷車海."],"6-5-2":["Dar las gracias a X: 向X道謝／致謝","Thank X: 向X道謝／致謝","Thank X: 向X道谢／致谢","「向 X 道謝」是對 X 說謝謝，「致謝」比較正式，常用在演講或書面。","「向 X 道谢」是对 X 说谢谢，「致谢」比较正式，常用在演讲或书面。","向 X 道謝／致謝 = «dar las gracias a X». 道謝 es neutro y de uso cotidiano; 致謝 es más formal (discursos, escritos). Se puede añadir 說: 向他說謝謝.","向 X 道謝／致謝 means 'to thank X'. 道謝 is everyday, 致謝 is more formal (speeches, writing)."],"6-5-3":["Formar (talento): 培養出（了）","Cultivate / produce (people): 培養出（了）","Cultivate / produce (people): 培养出（了）","「培養出（了）＋人才」表示經過教育或訓練，造就出某種人才或能力。主詞常是學校、政策或家庭。","「培养出（了）＋人才」表示经过教育或训练，造就出某种人才或能力。主词常是学校、政策或家庭。","培養出（了）+ tipo de persona = «formar / haber formado a…». 培養 se usa con talentos, hábitos o capacidades; 出 indica que se obtiene un resultado. Sujeto típico: escuela, política, familia.","培養出（了）+ type of person means a school, policy or family has nurtured and produced such people or abilities."],"6-5-4":["Principalmente: 主要是","Mainly: 主要是","","「主要是……」用來指出眾多原因或項目裡最重要的一個，常說「主要是因為……」。","「主要是……」用来指出众多原因或项目里最重要的一个，常说「主要是因为……」。","主要是 + razón/elemento = «sobre todo es / se debe principalmente a…». Se usa para señalar la causa más importante entre varias; muy frecuente con 因為: 主要是因為….","主要是… singles out the most important reason or element among several; often 主要是因為…"],"6-5-5":["Conectar con X: 跟X接軌","Be in line with X","","「跟 X 接軌」本來是鐵軌接在一起，比喻和 X（國際、社會、市場）連接、同步，也說「與國際接軌」。","「跟 X 接轨」本来是铁轨接在一起，比喻和 X（国际、社会、市场）连接、同步，也说「与国际接轨」。","跟 X 接軌 = «conectarse / alinearse con X» (el mundo, el mercado, los estándares internacionales). Literalmente «unir los rieles». Se usa para integrarse en un sistema o estándar más amplio: 與國際接軌.","跟 X 接軌 literally 'to join the rails'; figuratively to link up with / align with X (the world, society, the market): also 與國際接軌."],"6-5-6":["Ser dejado atrás: 被X（給）拋在後（面）","Be left behind by X","","「A 被 X（給）拋在後（面）」是 A 被 X 超過、落在後面。「給」讓語氣比較口語。可以是比賽，也可以比喻落後。","「A 被 X（给）抛在后（面）」是 A 被 X 超过、落在后面。「给」让语气比较口语。可以是比赛，也可以比喻落后。","A 被 X（給）拋在後（面）= «A es dejado atrás por X». Es una pasiva con 被: X es quien avanza más rápido y A se queda rezagado. 給 refuerza el tono coloquial. Sentido literal (carrera) o figurado.","A 被 X（給）拋在後（面）: A is left behind (outpaced) by X. 給 adds a colloquial touch. Literal (races) or figurative."],"6-5-7":["Multiplicarse: 倍增","Multiply / double (or more): 倍增","","「倍增」是數量增加好幾倍（至少一倍），後面不接受詞，語氣較正式，常用於收入、人數、風險等。","「倍增」是数量增加好几倍（至少一倍），后面不接受词，语气较正式，常用于收入、人数、风险等。","倍增 = «multiplicarse / aumentar varias veces» (por lo menos se duplica). Se usa con ingresos, cantidad, riesgo; es un verbo intransitivo, sin objeto, y formal.","倍增 means to multiply by a factor (at least double). It takes no object and is formal; used for income, numbers, risk."],"6-5-8":["Tener cierto X: 有一定的X","Have a certain (degree of) X","","「有一定的 X」的「一定」是「某個程度」的意思，不是「必定」，表示有某種程度的 X，常見搭配有影響、幫助、程度、難度。","「有一定的 X」的「一定」是「某个程度」的意思，不是「必定」，表示有某种程度的 X，常见搭配有影响、帮助、程度、难度。","有一定的 + sustantivo abstracto = «tener cierto/a… (influencia, efecto, impacto, límite)». 一定 aquí no es «seguro», sino «determinado, cierto grado». Suele ser un grado moderado y razonable. Colocaciones: 有一定的影響／幫助／程度.","有一定的 X: here 一定 means 'a certain degree of', not 'definitely'. Common with 影響, 幫助, 程度, 難度."],"6-5-9":["Atraer a X para que venga: 吸引X前來","Attract X to come","","「吸引 X 前來」是讓 X 被吸引而來到這裡。「前來」是比較正式的「來」，相反的是「前往」。","「吸引 X 前来」是让 X 被吸引而来到这里。「前来」是比较正式的「来」，相反的是「前往」。","吸引 X 前來 = «atraer a X para que venga». 前來 = venir hacia aquí (formal), con 前往 como contrario (ir hacia allá). El sujeto es lo que atrae (un sonido, un precio, un evento).","吸引 X 前來 means to attract X so that they come. 前來 is a formal 'come' (opposite: 前往 'go')."],"6-5-10":["Desde el punto de vista de X: 從X（的）角度來看","From the perspective of X","","「從 X（的）角度來看」是站在 X 的立場或方面來看事情，後面說看法。X 可以是人、立場或主題。","「从 X（的）角度来看」是站在 X 的立场或方面来看事情，后面说看法。X 可以是人、立场或主题。","從 X（的）角度來看 = «desde el punto de vista de X». X es una persona, una posición o un tema (環保、消費者、老師). Después se da un juicio o una conclusión. También: 從 X 來看, 從 X 的立場來說.","從 X（的）角度來看 means 'from X's point of view'; X can be a person, position or topic, followed by a judgment."],"6-6-0":["Cambio de X a Y: 由X轉Y","Change from X to Y: 由X轉Y","Change from X to Y: 由X转Y","表示情況從 X 的狀態逐漸變成 Y 的狀態，常用在天氣、心情、局勢等變化，偏書面。","表示情况从 X 的状态逐渐变成 Y 的状态，常用在天气、心情、局势等变化，偏书面。","由 X 轉 Y = cambiar de X a Y. Describe un cambio de estado, sobre todo en clima, ánimo o situación; X e Y suelen ser adjetivos opuestos. Es más escrito que hablado.","Describes a gradual change from state X to state Y (weather, mood, situation). More written in style."],"6-6-1":["Remontarse a: 追溯至／到","Trace back to: 追溯至／到","","往過去查找事情的起點或源頭，後面接時間或事件。書面用法，常說「可以追溯到……」。","往过去查找事情的起点或源头，后面接时间或事件。书面用法，常说「可以追溯到……」。","追溯至／到 = remontarse a, tener su origen en. Se usa para rastrear el origen de algo en el pasado y va seguido de una época o un hecho. Es de registro escrito; es frecuente «可以追溯到…».","Traces something back to its origin in the past; followed by a time or event. Written style, often 可以追溯到…."],"6-6-2":["Para expresar gratitud: 以表……的謝意","To express thanks: 以表……的謝意","To express thanks: 以表……的谢意","表示做某件事是為了表達感謝，用在正式、書面的場合（如公告、致詞）。口語不常這樣說。","表示做某件事是为了表达感谢，用在正式、书面的场合（如公告、致词）。口语不常这样说。","以表（對）…的謝意 / 為表（對）…的謝意 = para expresar nuestro agradecimiento por…. Es muy formal (comunicados, discursos). Se coloca después de la acción: «hacemos X para agradecer…».","Shows that something is done to express thanks; used in formal or written settings (announcements, speeches), rarely in speech."],"6-6-3":["A partir de entonces: 自此","From then on: 自此","","從某個時間點開始，後面一直是同一種情況。偏書面，相當於「從此」。","从某个时间点开始，后面一直是同一种情况。偏书面，相当于「从此」。","自此 = a partir de entonces, desde ese momento. Marca un punto de inicio tras el cual la situación continúa. Es más escrito que 從此 o 從那以後, y va antes del verbo.","From a certain point on, a new situation continues. Written style; similar to 從此."],"6-6-4":["Ser aficionado a: 熱衷於","Be keen on: 熱衷於","Be keen on: 热衷于","對某件事非常有興趣、很投入。後面接活動或事物，常見於書面或較正式的說法。","对某件事非常有兴趣、很投入。后面接活动或事物，常见于书面或较正式的说法。","熱衷於 = ser muy aficionado a, estar entusiasmado con. Va seguido de una actividad o cosa. Puede tener matiz de exceso (como en el ejemplo), según el contexto. Registro algo formal.","Being very keen on and devoted to something; followed by an activity or thing. Common in written or formal speech."],"6-6-5":["Respectivamente, por separado: 分別","Respectively: 分別","Respectively: 分别","表示兩個以上的人或事物各自做某事、各有某種情況，放在動詞前。","表示两个以上的人或事物各自做某事、各有某种情况，放在动词前。","分別 = respectivamente, cada uno por separado. Se pone antes del verbo y presupone dos o más sujetos o elementos que se tratan de forma individual. No es el 分別 de «despedirse» ni el de «diferencia».","Shows that two or more people or things each do something or have something separately; placed before the verb."],"6-6-6":["Fijar condiciones: 設下……的條件","Set conditions: 設下……的條件","Set conditions: 设下……的条件","訂出某些要求或限制，「條件」前面放具體內容。偏正式，用於規定、申請、談判。","订出某些要求或限制，「条件」前面放具体内容。偏正式，用于规定、申请、谈判。","設下…的條件 = establecer la condición de…. El contenido concreto de la condición va antes de 的條件. Es de tono formal (trámites, reglamentos, negociaciones). También se dice 訂下條件 o 設定條件.","Setting out requirements or restrictions, with the specific content before 條件. Fairly formal; used for rules, applications, negotiations."],"6-6-7":["Sufrir (algo negativo): 遭（X）……","Suffer (something bad): 遭（X）……","","表示碰到不好的事，像被淘汰、被拒絕。後面多是動詞或帶有負面意思的詞，書面語氣。","表示碰到不好的事，像被淘汰、被拒绝。后面多是动词或带有负面意思的词，书面语气。","遭（X）… = sufrir, ser víctima de (algo adverso). Sirve como una pasiva de sentido negativo, más escrita que 被. Va seguido de un verbo o nombre negativo (遭淘汰, 遭拒絕, 遭殃). No se usa con hechos positivos.","Meets something unfortunate, such as being eliminated or rejected; usually followed by a verb or a negative word. Written tone."],"6-6-8":["Por eso: 因而","Therefore: 因而","","表示前面的原因造成後面的結果，相當於「所以」，但更書面，常用在句子中間。","表示前面的原因造成后面的结果，相当于「所以」，但更书面，常用在句子中间。","因而 = por eso, de ahí que. Une una causa con su consecuencia como 所以, pero es más escrito y suele ir en medio de la oración (no al inicio con sujeto propio). No se combina con 因為 en la misma cláusula.","Shows that the preceding reason leads to the result; like 所以 but more written, often in the middle of a sentence."],"6-6-9":["Cambiar a (una modalidad): 改由……（方式）","Switch to…: 改由……（方式）","","表示原來的做法不用了，換成另一種人或方式來做。「由」後面可以是人，也可以是方式，常接「方式」。","表示原来的做法不用了，换成另一种人或方式来做。「由」后面可以是人，也可以是方式，常接「方式」。","改由…（方式）= pasar a hacerse por…, cambiar a… Indica que se abandona la forma anterior y otra persona o modalidad toma su lugar. 由 introduce al agente o al método. Frecuente en explicaciones y descripciones.","Says the old way is dropped and replaced by another person or method; after 由 can be a person or a method, often followed by 方式."],"6-6-10":["Abrir la puerta a…: 打開……的大門","Open the door to…: 打開……的大門","Open the door to…: 打开……的大门","比喻讓某個機會、領域或關係開始出現。「的大門」前面放要開放的對象，書面、新聞常用。","比喻让某个机会、领域或关系开始出现。「的大门」前面放要开放的对象，书面、新闻常用。","打開…的大門 = abrir las puertas a…. Metáfora que significa dar paso a una oportunidad, un ámbito o una relación. Lo que se abre va antes de 的大門. Frecuente en prensa y textos formales.","A metaphor for opening up an opportunity, field or relationship; the thing being opened goes before 的大門. Common in writing and news."],"6-6-11":["En nombre de / bajo la figura de: 以X的名義","In the name of X: 以X的名義","In the name of X: 以X的名义","表示用某種身分、理由或名稱來做事，X 可能是真實的身分，也可能只是名義。","表示用某种身分、理由或名称来做事，X 可能是真实的身分，也可能只是名义。","以 X 的名義 = en nombre de X, bajo el título/pretexto de X. Indica la calidad o el motivo con el que se hace algo; X puede ser una función real o solo un pretexto, según el contexto.","Doing something under a certain status, reason or name; X may be a genuine capacity or just a pretext."],"6-7-0":["En el momento de…: 在……（的）當下","At the moment of…: 在……（的）當下","At the moment of…: 在……（的）当下","指事情發生的那一刻，「當下」前面放事件或動作。書面或較正式，也可只說「當下」。","指事情发生的那一刻，「当下」前面放事件或动作。书面或较正式，也可只说「当下」。","在…（的）當下 = en el momento en que…, en el acto de…. Marca el instante exacto de un suceso, que va antes de 當下. Más escrito; 當下 solo también significa «en ese momento».","Means at the very moment something happens; the event goes before 當下. Written or formal; can also be just 當下."],"6-7-1":["Ser fiel a: 忠於","Be faithful to: 忠於","Be faithful to: 忠于","對人、理想、原則等保持忠誠，不背叛。後面接人或抽象的對象，較書面。","对人、理想、原则等保持忠诚，不背叛。后面接人或抽象的对象，较书面。","忠於 = ser fiel a, mantenerse leal a. Va seguido de una persona, ideal, principio o también «uno mismo» (忠於自己). Registro escrito. En el ejemplo se usa con matiz de «apegarse demasiado» a la lengua materna.","Remaining loyal to a person, ideal or principle; followed by a person or abstract thing. Rather written."],"6-7-2":["Aunque…, igualmente…: 縱使……，也……","Even if…, still…: 縱使……，也……","Even if…, still…: 纵使……，也……","表示就算出現很不利的情況，結果或決定也不會改變。比「即使」更書面，後半句常有「也」。","表示就算出现很不利的情况，结果或决定也不会改变。比「即使」更书面，后半句常有「也」。","縱使…，也… = aun si…, de todas formas…. Concesiva literaria, más escrita que 即使; la segunda parte lleva 也 y expresa que la decisión no cambia. Introduce una hipótesis desfavorable (no un hecho ya ocurrido).","Even if a very unfavorable situation arises, the result or decision stays the same. More written than 即使; the second clause usually has 也."],"6-7-3":["Autoproclamarse: 自詡為X","Style oneself as X: 自詡為X","Style oneself as X: 自诩为X","自己認為、並向別人說自己是某種很好的人或專家，常帶有「未必真是這樣」的諷刺意味。","自己认为、并向别人说自己是某种很好的人或专家，常带有「未必真是这样」的讽刺意味。","自詡為 X = autoproclamarse X, presumir de ser X. Alguien se atribuye un título o cualidad positiva; con frecuencia implica ironía o cierta duda del hablante. Registro escrito.","Calling oneself something impressive, such as an expert; often with an ironic hint that it may not be true."],"6-7-4":["Llevar X al máximo: 把X發揮到極致","Take X to the fullest: 把X發揮到極致","Take X to the fullest: 把X发挥到极致","把某種能力、特色或味道表現到最好、最完整的程度。X 是被發揮的對象，語氣褒義。","把某种能力、特色或味道表现到最好、最完整的程度。X 是被发挥的对象，语气褒义。","把 X 發揮到極致 = llevar X a su máxima expresión. Estructura con 把: X es la cualidad, habilidad o característica que se explota al máximo. Tono positivo, frecuente en elogios.","Bringing an ability, feature or flavor to its fullest, best expression. X is what is brought out; positive tone."],"6-7-5":["Sin poder evitarlo: 不由自主地","Involuntarily: 不由自主地","","沒辦法控制自己，身體或情緒自然就做出某個動作或反應。放在動詞前，用「地」連接。","没办法控制自己，身体或情绪自然就做出某个动作或反应。放在动词前，用「地」连接。","不由自主地 = involuntariamente, sin poder evitarlo. Describe una reacción física o emocional que uno no controla. Va antes del verbo con 地; suele hablar de emociones, risas, lágrimas o impulsos.","Unable to control oneself; the body or emotions react on their own. Placed before the verb, linked with 地."],"6-7-6":["Ponerse del mismo lado: 和X站在同一陣線","Be on the same side as X: 和X站在同一陣線","Be on the same side as X: 和X站在同一阵线","與某人立場一致、共同對抗另一方。常見於政治、爭論或競爭場合，「陣線」是比喻。","与某人立场一致、共同对抗另一方。常见于政治、争论或竞争场合，「阵线」是比喻。","和 X 站在同一陣線 = estar del mismo lado que X, unirse a X frente a un tercero. «陣線» (frente) es metafórico. Se usa en política, debates y conflictos; el contrario es 站在對立面.","Sharing someone's stance and facing the other side together; common in politics, debates and competition; 陣線 is figurative."],"6-7-7":["Usar y tirar: X過即Y","Use then discard: X過即Y","Use then discard: X过即Y","表示做完 X 之後馬上做 Y，常用來形容「用過就丟」這類一次性的東西。X 通常是動詞，格式像成語，偏書面。","表示做完 X 之后马上做 Y，常用来形容「用过就丢」这类一次性的东西。X 通常是动词，格式像成语，偏书面。","X 過即 Y = una vez X, enseguida Y. Estructura de aire clásico: tras hacer X se hace Y inmediatamente; la usan expresiones como 用過即丟 (usar y tirar) o 看過即焚. X suele ser un verbo monosilábico. Registro escrito.","Means doing Y right after X, often describing single-use things like 用過即丟. X is usually a verb; idiom-like and written."],"6-7-8":["Ni tener en cuenta: ……（都）看在眼裡","Take into account/regard: ……（都）看在眼裡","Take into account/regard: ……（都）看在眼里","字面是「放在眼裡」。肯定時表示在意、重視；否定「不看在眼裡」表示瞧不起或毫不在乎。","字面是「放在眼里」。肯定时表示在意、重视；否定「不看在眼里」表示瞧不起或毫不在乎。","…（都）看在眼裡 = tener en cuenta / darle importancia a…. En afirmativo indica que algo importa o se aprecia; en negativo (不看在眼裡) significa no darle importancia o menospreciar. En el ejemplo: «la fama y el dinero nunca le importaron».","Literally 'put in one's eyes'. Affirmative shows concern or esteem; the negative 不看在眼裡 means disregard or not caring."],"6-7-9":["Comparar y sacar lo común: V（出）其中的共同點","Draw out the common points: V（出）其中的共同點","Draw out the common points: V（出）其中的共同点","動詞（比較、找、歸納、看）加「出」表示從一些事物裡把共同的地方找出來或整理出來。","动词（比较、找、归纳、看）加「出」表示从一些事物里把共同的地方找出来或整理出来。","V（出）其中的共同點 = hallar/sacar los puntos en común entre ellos. Un verbo (比較, 找, 歸納, 看) con el complemento 出 expresa extraer o identificar algo de un conjunto. «其中» remite a los elementos ya mencionados.","A verb (compare, find, sum up, see) plus 出 shows picking out or identifying the shared point among things."],"6-7-10":["Existe la posibilidad de…: 有……的可能","There is a possibility of…: 有……的可能","","說某件事有可能發生，「的可能」前面是事件。常用於報導、分析，語氣比「可能」更客觀。","说某件事有可能发生，「的可能」前面是事件。常用于报导、分析，语气比「可能」更客观。","有…的可能 = existe la posibilidad de…. Tras 有 va el suceso y luego 的可能. Es un registro más objetivo, propio de informes y análisis. También en negativo: 沒有…的可能.","Says something may happen; the event goes before 的可能. Common in reports and analyses, more objective in tone than 可能."],"6-8-0":["Después de pasar por…: 在歷經……之後","After going through…: 在歷經……之後","After going through…: 在历经……之后","經過一連串（通常是困難或長期的）事情以後。「歷經」多接重大、辛苦的經驗，書面。","经过一连串（通常是困难或长期的）事情以后。「历经」多接重大、辛苦的经验，书面。","在歷經…之後 = tras haber pasado por…. 歷經 se usa con experiencias importantes o duras (crisis, años de esfuerzo) y es de registro escrito. Equivale a «después de atravesar…».","After going through a series of (usually hard or long) events; 歷經 takes serious or arduous experiences. Written."],"6-8-1":["Tantos como…: ……之多，是……","As many as…: ……之多，是……","","先說數量非常多（「之多」表示多到令人驚訝），再說比較的結果，常是「是……的幾倍」。","先说数量非常多（「之多」表示多到令人惊讶），再说比较的结果，常是「是……的几倍」。","…之多，是… = tantos como…, hasta… (más que…). 之多 subraya que la cantidad es sorprendentemente grande; luego se compara, a menudo con «es N veces…». Registro escrito, común en noticias.","First says the amount is large (之多 implies surprisingly many), then gives the comparison, often 'X times as many as…'."],"6-8-2":["Desde siempre: 一直以來","All along: 一直以來","All along: 一直以来","從過去某個時候一直到現在，情況沒有改變。放在句首或主語後面，常接「都」。","从过去某个时候一直到现在，情况没有改变。放在句首或主语后面，常接「都」。","一直以來 = desde siempre, durante todo este tiempo (hasta ahora). Expresa continuidad desde el pasado hasta el presente; suele ir al comienzo de la oración o tras el sujeto, con frecuencia seguido de 都.","From some time in the past until now, with no change; placed at the start of a sentence or after the subject, often with 都."],"6-8-3":["Ver como muestra de…: 視為……的展現","Regard as a display of…: 視為……的展現","Regard as a display of…: 视为……的展现","把某個行為看成是某種特質、能力的表現。前面常有主語，「視為」是「把……看成」，書面。","把某个行为看成是某种特质、能力的表现。前面常有主语，「视为」是「把……看成」，书面。","視為…的展現 = considerar (algo) una muestra de…. 視為 equivale a «considerar como»; 展現 es la manifestación de una cualidad o capacidad. Registro escrito, frecuente en comentarios y noticias.","Regards a behavior as a display of a quality or ability; 視為 means 'regard as', written style."],"6-8-4":["Volver a / ser devuelto a: 歸於","Return to: 歸於","Return to: 归于","回到某處或進入某種狀態，如「歸於平靜」「歸於山林」。書面，常見固定搭配。","回到某处或进入某种状态，如「归于平静」「归于山林」。书面，常见固定搭配。","歸於 = volver a, regresar a (un lugar o estado). Aparece en combinaciones fijas como 歸於平靜 (volver a la calma) o 歸於山林 (volver a los montes). Es de registro escrito y requiere un destino o estado que lo complete.","Returning to a place or entering a state, as in 歸於平靜 or 歸於山林. Written, mostly fixed collocations."],"6-8-5":["X es Y: X即是Y","X is precisely Y: X即是Y","","「即是」相當於「就是」，用來直接說明 X 的意思或本質，常用來下定義、說道理，書面。","「即是」相当于「就是」，用来直接说明 X 的意思或本质，常用来下定义、说道理，书面。","X 即是 Y = X es precisamente Y. 即是 es la versión escrita de 就是 y sirve para definir o afirmar la esencia de algo. En el ejemplo: «lo que más anhela el ser humano es ser reconocido».","即是 equals 就是 and states directly what X means or is; used for definitions and statements, written."],"6-8-6":["Mucho después de…: 遠在……之後","Long after…: 遠在……之後","Long after…: 远在……之后","表示時間比某個基準時間晚很多。「遠」強調差得很多，也可與「之前」對比成「遠在……之前」。","表示时间比某个基准时间晚很多。「远」强调差得很多，也可与「之前」对比成「远在……之前」。","遠在…之後 = mucho después de…. 遠 enfatiza la gran distancia temporal respecto de un punto de referencia; su opuesto es 遠在…之前 (mucho antes de…). Registro escrito.","Says the time is much later than a reference time; 遠 stresses the large gap; the counterpart is 遠在…之前."],"6-8-7":["X supera a Y en N veces o más: X比Y多（了）N倍有餘","More than N times as many: X比Y多（了）N倍有餘","More than N times as many: X比Y多（了）N倍有余","表示 X 比 Y 多出 N 倍還不止。「有餘」是「超過」，用在數量的比較，書面。","表示 X 比 Y 多出 N 倍还不止。「有余」是「超过」，用在数量的比较，书面。","X 比 Y 多（了）N 倍有餘 = X supera a Y en más de N veces. 有餘 significa «y más». Atención: en chino «多 N 倍» suele entenderse como N veces más (X = (N+1)·Y). Estilo escrito, de comparación numérica.","Says X exceeds Y by more than N times; 有餘 means 'with some to spare'. For comparing quantities, written."],"6-8-8":["Terminar en…: 以……收場","End in…: 以……收場","End in…: 以……收场","表示事情最後的結果或結束方式。「收場」前面常放「失敗」「悲劇」「和局」等，多帶遺憾或負面意味。","表示事情最后的结果或结束方式。「收场」前面常放「失败」「悲剧」「和局」等，多带遗憾或负面意味。","以…收場 = terminar en…, acabar con…. Indica el modo en que concluye algo; lo habitual es que lo antecedan resultados no deseados (失敗, 悲劇, 道歉). Registro escrito.","Shows how something ends or turns out; 失敗, 悲劇, 和局 and so on often precede 收場, usually with a regrettable or negative sense."],"6-8-9":["Significar: 意味著","Mean/imply: 意味著","Mean/imply: 意味着","表示某件事帶有或顯示出某種含義、結果。主語常是現象或情況，後面接結論，書面。","表示某件事带有或显示出某种含义、结果。主语常是现象或情况，后面接结论，书面。","意味著 = significar, implicar. El sujeto suele ser un hecho o fenómeno, y lo que sigue es la conclusión o consecuencia. Propio del registro escrito. No se usa para el «significado» de una palabra (para eso, 意思是).","Shows that something implies or indicates a certain meaning or result. The subject is often a phenomenon; a conclusion follows. Written."],"6-8-10":["Asumir: 接下","Take on: 接下","","接受並負責某個工作、責任或任務。「接下」是 V＋下，表示承接。常和「責任」「工作」「重擔」搭配。","接受并负责某个工作、责任或任务。「接下」是 V＋下，表示承接。常和「责任」「工作」「重担」搭配。","接下 = asumir, hacerse cargo de (una tarea o responsabilidad). Se usa con 責任, 工作, 重擔, 任務. «下» indica que se recibe y se acepta. No es «recibir» físicamente un objeto (eso es 接到).","Accepting and taking charge of a job, responsibility or task. 接下 is V+下, meaning taking over; often with 責任, 工作, 重擔."],"6-8-11":["Provenir de / lograrse mediante: 經由……而來","Come through…: 經由……而來","Come through…: 经由……而来","表示某種結果或能力是透過某個方式、途徑得來的。「經由」後接途徑，「而來」收尾，書面。","表示某种结果或能力是透过某个方式、途径得来的。「经由」后接途径，「而来」收尾，书面。","經由…而來 = provenir de, lograrse a través de…. 經由 introduce el medio o proceso y 而來 cierra la estructura. Enfatiza que algo se obtiene mediante un cierto camino (entrenamiento, aprendizaje). Registro escrito.","Shows that a result or ability is obtained through a certain way or route; 經由 introduces the route, 而來 closes it. Written."],"6-8-12":["Además: 再者","Moreover: 再者","","用來追加另一個理由或情況，位置在後面的分句開頭。書面，常用在議論裡，口語多說「而且」。","用来追加另一个理由或情况，位置在后面的分句开头。书面，常用在议论里，口语多说「而且」。","再者 = además, por otra parte. Añade otra razón o circunstancia al inicio de la siguiente cláusula. Es de registro escrito y argumentativo; en lo oral se prefiere 而且 o 還有.","Adds another reason or circumstance; placed at the start of the later clause. Written, common in argumentation; in speech people usually say 而且."],"6-8-13":["Un descuido: 一個不小心","One careless moment: 一個不小心","One careless moment: 一个不小心","表示稍微一疏忽就會出現（壞）結果。常放在句首或主句前，後面接可能發生的壞事，常帶「就」。","表示稍微一疏忽就会出现（坏）结果。常放在句首或主句前，后面接可能发生的坏事，常带「就」。","一個不小心 = por un descuido, si uno se descuida. Indica que un pequeño error lleva a un mal resultado; suele ir al inicio y va seguido de 就 + consecuencia. Informal-neutral.","Says that a slight lapse leads to a (bad) result; typically at the start of a sentence, followed by what might happen, often with 就."],"6-8-14":["No se puede dejar de…: 不可不……","Must not fail to…: 不可不……","","雙重否定，意思是「一定要」「必須」，語氣比「必須」更強調或勸告。後面是動詞，書面或勸告時用。","双重否定，意思是「一定要」「必须」，语气比「必须」更强调或劝告。后面是动词，书面或劝告时用。","不可不… = no se puede dejar de…, hay que… sí o sí. Es doble negación que equivale a «es imprescindible»; suena a recomendación enfática o consejo. Va seguida de un verbo y es de registro más escrito. No confundir con 不可以 (prohibición).","A double negative meaning 'must'; stronger or more of a recommendation than 必須. A verb follows; written or advisory."],"6-9-0":["Si lo calculamos…: 算計起來","All told: 算計起來","All told: 算计起来","把時間、數量或花費加總計算後得到的結果，常接「已經……了」，用來說明總共多久、多少。","把时间、数量或花费加总计算后得到的结果，常接「已经……了」，用来说明总共多久、多少。","算計起來 = haciendo las cuentas, si se calcula. Presenta el resultado de sumar tiempo, cantidad o gasto; suele ir seguido de «ya llevan… / ya son…». Nota: 算計 solo, como verbo, también significa «tramar contra alguien».","The result of totaling up time, quantity or cost, often followed by 已經……了 to say how long or how much in all."],"6-9-1":["Sin darse cuenta: （在）不知不覺中","Without realizing: （在）不知不覺中","Without realizing: （在）不知不觉中","沒有注意到的時候，事情已經慢慢變化或發生了。放在句首或主語後，表示過程不明顯。","没有注意到的时候，事情已经慢慢变化或发生了。放在句首或主语后，表示过程不明显。","（在）不知不覺中 = sin darse cuenta, imperceptiblemente. Indica que un cambio ocurre poco a poco sin que se note; suele ir al inicio de la oración o tras el sujeto. Neutro, usable en hablado y escrito.","While not noticing, something has gradually changed or happened. Placed at the start or after the subject, showing an unnoticeable process."],"6-9-2":["Cosas como…: ……之類的N","Things like…: ……之類的N","Things like…: ……之类的N","列出一兩個例子，再用「之類的」概括同類事物，後面接名詞。意思是「像……這一類的」。","列出一两个例子，再用「之类的」概括同类事物，后面接名词。意思是「像……这一类的」。","…之類的 N = N como…, N de ese tipo. Se citan uno o dos ejemplos y 之類的 abarca la categoría; después va el sustantivo (收入, 食物, 工作…). Es más general que 等等 y algo coloquial.","Gives one or two examples, then 之類的 covers the same kind of things, followed by a noun. Means 'things like…'."],"6-9-3":["Uno por uno: 一一","One by one: 一一","","表示一個接一個、逐項地做，不遺漏。放在動詞前，書面或正式。","表示一个接一个、逐项地做，不遗漏。放在动词前，书面或正式。","一一 = uno por uno, uno a uno, sin omitir ninguno. Va antes del verbo y recalca que se hace de manera individual y completa. Registro escrito o formal. No es el número «11».","Doing something one after another, item by item, without missing any; placed before the verb; written or formal."],"6-10-0":["Hasta cierto punto: 某種程度來說","To some extent: 某種程度來說","To some extent: 某种程度来说","表示「在某個範圍或意義上」，用來讓說法比較保守、不絕對。常放在句子前面，口語與書面都能用。","表示「在某个范围或意义上」，用来让说法比较保守、不绝对。常放在句子前面，口语与书面都能用。","某種程度來說 = hasta cierto punto, en cierto sentido. Matiza una afirmación para que no sea absoluta. Va al inicio de la oración o tras el sujeto. Se usa tanto en lo oral como en lo escrito; también «某種程度上».","Means 'in a certain sense or to some extent', making a claim less absolute. Often at the start of a sentence, usable in speech and writing."],"6-10-1":["Confundir X con Y: 把X和Y混為一談","Lump X and Y together: 把X和Y混為一談","Lump X and Y together: 把X和Y混为一谈","把本來不同的兩件事當成同一件事來談，常用來批評別人搞混了。有負面、指出錯誤的語氣。","把本来不同的两件事当成同一件事来谈，常用来批评别人搞混了。有负面、指出错误的语气。","把 X 和 Y 混為一談 = confundir X con Y, meter a X e Y en el mismo saco. Se critica que se traten como lo mismo dos cosas diferentes. Tono negativo; suele ir en estructuras con 不能 o 不要.","Treating two different things as one; often used to criticize mixing them up. Negative, pointing out an error."],"6-10-2":["Sufrir por: 為……所苦","Be plagued by…: 為……所苦","Be plagued by…: 为……所苦","被某個困難或問題困擾、折磨。「為……所」是被動的書面格式，後面常接「苦、困擾、擾」。","被某个困难或问题困扰、折磨。「为……所」是被动的书面格式，后面常接「苦、困扰、扰」。","為…所苦 = sufrir de, estar atormentado por…. 為…所 es una pasiva escrita clásica; 所苦 indica el tormento. Se usa con problemas persistentes (病痛, 失眠, 貧窮). Registro formal/escrito.","Troubled or tormented by some difficulty or problem. 為……所 is a written passive pattern, often followed by 苦, 困擾, 擾."],"6-10-3":["No dañar (su…): 不損（其）……","Not harm its…: 不損（其）……","Not harm its…: 不损（其）……","表示不會損害、減少某個事物的好處。「其」指前面提到的東西，「損」是損害，文言口吻的書面語。","表示不会损害、减少某个事物的好处。「其」指前面提到的东西，「损」是损害，文言口吻的书面语。","不損（其）… = no perjudica (su…), no merma (su…). 其 remite al objeto ya mencionado; 損 es «dañar». Estilo escrito de aire clásico; puede decirse más llanamente 不會損失它的…. Se combina con 並不 (並不損其營養).","Says it will not harm or reduce the benefit of something; 其 refers to the earlier item and 損 means damage. Classical-sounding written style."],"6-10-4":["No estorbar: 不礙","Not hinder: 不礙","Not hinder: 不碍","表示不會妨礙、不會影響。後面常接「其／事／正事」等，是文言口吻的書面語，與「不損」類似。","表示不会妨碍、不会影响。后面常接「其／事／正事」等，是文言口吻的书面语，与「不损」类似。","不礙 = no obstaculiza, no impide. Suele ir seguido de 其, 事, 正事, etc. Registro escrito de aire clásico (similar a 不損). Es más coloquial decir 不會妨礙 / 不影響.","Means it will not hinder or affect; often followed by 其, 事, 正事, etc. Classical-sounding written style, like 不損."],"6-10-5":["El espíritu de X reside en…: X的精神在（於）……","The essence of X lies in…: X的精神在（於）……","The essence of X lies in…: X的精神在（于）……","說明某種事物最核心的想法或原則是什麼。X 是制度、教育、理念等，「在於」引出重點，書面。","说明某种事物最核心的想法或原则是什么。X 是制度、教育、理念等，「在于」引出重点，书面。","X 的精神在（於）… = el espíritu de X radica en…. Introduce la esencia o principio central de algo (un sistema, una educación, un ideal). 在於 introduce lo esencial. Registro escrito, común en definiciones y explicaciones.","Explains the core idea or principle of something (system, education, ideal); 在於 introduces the key point. Written."],"6-10-6":["Lograr / poder (por fin): 得以","Be able to (thanks to…): 得以","","表示因為有了某個條件或機會，才能夠做到某事，常有「終於可以」的意思。放在動詞前，書面。","表示因为有了某个条件或机会，才能够做到某事，常有「终于可以」的意思。放在动词前，书面。","得以 = poder, lograr (gracias a una condición u oportunidad). Va antes del verbo y suele implicar que algo antes imposible ahora es posible. Registro escrito. A diferencia de 可以, no expresa permiso, y el sujeto no suele ser quien decide.","Shows that thanks to a condition or opportunity one is able to do something, often 'finally can'. Placed before the verb; written."],"6-10-7":["Con algún V (leve): 有所V","To some extent V: 有所V","","表示「有一些……」，程度不深，後面接雙音節動詞，如「有所改善」「有所期待」。書面，語氣比較客觀、保守。","表示「有一些……」，程度不深，后面接双音节动词，如「有所改善」「有所期待」。书面，语气比较客观、保守。","有所 V = V en cierta medida, algo de V. Va con verbos bisílabos (改善, 期待, 幫助, 了解). Indica un grado moderado y es de registro escrito y objetivo. No se usa con verbos monosilábicos ni con complementos de grado.","Means 'to some degree', not deep; a two-syllable verb follows, as in 有所改善 or 有所期待. Written, objective and measured."],"6-10-8":["Distinguir X de Y: 區分（出）X和Y","Distinguish X from Y: 區分（出）X和Y","Distinguish X from Y: 区分（出）X和Y","把兩樣東西分辨出來，看出它們的不同。常和「不出」「得出」搭配：「區分不出X和Y」。","把两样东西分辨出来，看出它们的不同。常和「不出」「得出」搭配：「区分不出X和Y」。","區分（出）X 和 Y = distinguir X de Y. Se usa para reconocer la diferencia entre dos cosas; frecuente con complemento potencial: 區分不出 (no poder distinguir) / 區分得出. No es lo mismo que 分開, que significa «separar».","Telling two things apart and seeing their difference; often with 不出 or 得出, e.g., 區分不出X和Y."],"6-10-9":["Una de las formas de…: X是Y的方式之一","One of the ways of…: X是Y的方式之一","","說明 X 是達成 Y 的眾多方法中的一個。「之一」表示不是唯一，書面、議論時常用。","说明 X 是达成 Y 的众多方法中的一个。「之一」表示不是唯一，书面、议论时常用。","X 是 Y 的方式之一 = X es una de las maneras de Y. 之一 indica que hay otras opciones; es neutro y propio de la argumentación. Se puede sustituir 方式 por 方法, 途徑 o 手段.","Says X is one of several ways of achieving Y; 之一 shows it's not the only one. Common in written argument."],"6-10-10":["Todo (lo que sea): 凡是","Every / all…: 凡是","","表示在某一範圍內的所有人或事物都適用，後面常用「都、皆、無不」呼應。用於一般規則或事實，書面。","表示在某一范围内的所有人或事物都适用，后面常用「都、皆、无不」呼应。用于一般规则或事实，书面。","凡是 = todo lo que, todos los que. Se aplica a cualquier elemento de una categoría y la segunda parte lleva 都 / 皆 / 無不. Es normal que la cláusula con 凡是 sea una regla general. Registro escrito; también hablado con 只要是… .","Means everyone or everything within a range applies; often echoed by 都, 皆, 無不. For general rules or facts; written."],"6-10-11":["Resolver el misterio de…: 解開……之謎","Solve the mystery of…: 解開……之謎","Solve the mystery of…: 解开……之谜","把一直沒有答案的問題弄明白。「謎」前面放大家想知道的事，常見於新聞或科學報導。","把一直没有答案的问题弄明白。「谜」前面放大家想知道的事，常见于新闻或科学报导。","解開…之謎 = resolver el misterio de…, desentrañar el enigma de…. Lo que se quiere saber va antes de 之謎. Habitual en noticias y divulgación científica. El verbo 解開 también se usa con 結, 疑惑.","Finally clearing up a question that has long had no answer. What people want to know goes before 之謎; common in news or science reports."],"6-10-12":["Separar X de Y: 把X和Y分開","Separate X and Y: 把X和Y分開","Separate X and Y: 把X和Y分开","把原本有關聯的兩件事分成兩邊看待，不放在一起談。結構用「把」，後面常有「其實」引出作者的不同看法。","把原本有关联的两件事分成两边看待，不放在一起谈。结构用「把」，后面常有「其实」引出作者的不同看法。","把 X 和 Y 分開 = separar X de Y, tratar X e Y por separado. Estructura con 把. En el ejemplo, el autor critica esa separación y luego explica con 其實 que ambos se complementan. No lo confundas con 區分 (distinguir mentalmente).","Treats two related things as separate and doesn't discuss them together. Uses 把; 其實 often introduces the writer's different view."],"6-10-13":["Interiorizar X como Y: 把X內化為Y","Internalize X as Y: 把X內化為Y","Internalize X as Y: 把X内化为Y","把外面得到的東西，經過理解吸收，變成自己的一部分。X 是外來的經驗或知識，Y 是自己的能力或習慣，書面。","把外面得到的东西，经过理解吸收，变成自己的一部分。X 是外来的经验或知识，Y 是自己的能力或习惯，书面。","把 X 內化為 Y = interiorizar X convirtiéndolo en Y. Estructura 把 + 內化為: X es algo externo (experiencia, conocimiento) que se asimila hasta ser propio (Y). Registro académico y escrito.","Absorbing what comes from outside and making it part of oneself. X is external experience or knowledge, Y is one's own ability or habit; written."]});
